import { describe, expect, test } from "bun:test";
import { run } from "../src/lang";

const GREEN = "#16866a";

describe("interpreter: basic drawing", () => {
  test("a square of four forward moves and right turns", () => {
    const result = run("powtorz 4 [np 100 pw 90]", "2d");
