cat > lexer.ts <<'EOF'
export type TokenKind = "number" | "word" | "lbracket" | "rbracket";

export interface Token {
  kind: TokenKind;
  text: string;
  value: number;
  line: number;
  column: number;
}

export function tokenize(source: string): Token[] {
  const tokens: Token[] = [];
  let i = 0;
  let line = 1;
  let column = 1;
  const advance = () => {
    if (source[i] === "\n") {
      line++;
      column = 1;
    } else column++;
    i++;
  };
  while (i < source.length) {
    const ch = source[i];
    if (/\s/.test(ch)) {
      advance();
      continue;
    }
    const start = { line, column, i };
    if (ch === "[" || ch === "]") {
      advance();
      tokens.push({ kind: ch === "[" ? "lbracket" : "rbracket", text: ch, value: 0, ...start });
      continue;
    }
    while (i < source.length && !/[\s\[\]]/.test(source[i])) advance();
    const text = source.slice(start.i, i);
    if (/^\d+$/.test(text)) tokens.push({ kind: "number", text, value: Number(text), line: start.line, column: start.column });
    else tokens.push({ kind: "word", text, value: 0, line: start.line, column: start.column });
  }
  return tokens;
}
EOF
cat > index.ts <<'EOF'
import { tokenize, type Token } from "./lexer";
import type { Mode, RunResult, Segment, Vec3 } from "./types";

export type { Mode, RunResult, Segment, LogoError, Vec3 } from "./types";

type Stmt =
  | { kind: "np"; value: number }
  | { kind: "pw"; value: number }
  | { kind: "repeat"; count: number; body: Stmt[] };

function parse(tokens: Token[]): Stmt[] {
  let pos = 0;
  const block = (): Stmt[] => {
    const out: Stmt[] = [];
    while (pos < tokens.length && tokens[pos].kind !== "rbracket") {
      const t = tokens[pos++];
      const word = t.text.toLowerCase();
      if (word === "np") out.push({ kind: "np", value: tokens[pos++].value });
      else if (word === "pw") out.push({ kind: "pw", value: tokens[pos++].value });
      else if (word === "powtorz") {
        const count = tokens[pos++].value;
        pos++; // [
        const body = block();
        pos++; // ]
        out.push({ kind: "repeat", count, body });
      }
    }
    return out;
  };
  return block();
}

const cosd = (a: number) => (a % 90 === 0 ? [1, 0, -1, 0][(((a / 90) % 4) + 4) % 4] : Math.cos((a * Math.PI) / 180));
const sind = (a: number) => (a % 90 === 0 ? [0, 1, 0, -1][(((a / 90) % 4) + 4) % 4] : Math.sin((a * Math.PI) / 180));

export function run(source: string, _mode: Mode): RunResult {
  const program = parse(tokenize(source));
  const segments: Segment[] = [];
  let p: Vec3 = [0, 0, 0];
  let h: Vec3 = [0, 1, 0];
  let r: Vec3 = [1, 0, 0];
  const exec = (stmts: Stmt[]) => {
    for (const s of stmts) {
      if (s.kind === "np") {
        const to: Vec3 = [p[0] + h[0] * s.value, p[1] + h[1] * s.value, p[2] + h[2] * s.value];
        segments.push({ from: p, to, color: "#16866a", width: 3 });
        p = to;
      } else if (s.kind === "pw") {
        const c = cosd(s.value), sn = sind(s.value);
        const nh: Vec3 = [h[0] * c + r[0] * sn, h[1] * c + r[1] * sn, h[2] * c + r[2] * sn];
        const nr: Vec3 = [r[0] * c - h[0] * sn, r[1] * c - h[1] * sn, r[2] * c - h[2] * sn];
        h = nh;
        r = nr;
      } else for (let i = 0; i < s.count; i++) exec(s.body);
    }
  };
  exec(program);
  return { segments, error: null };
}
EOF
