const exact = [1, 0, -1, 0];
export function cosd(a: number): number {
  return a % 90 === 0 ? exact[(((a / 90) % 4) + 4) % 4] : Math.cos((a * Math.PI) / 180);
}
export function sind(a: number): number {
  return a % 90 === 0 ? exact[(((a / 90 + 3) % 4) + 4) % 4] : Math.sin((a * Math.PI) / 180);
}

const add = (a: Vec3, b: Vec3, k: number): Vec3 => [a[0] + b[0] * k, a[1] + b[1] * k, a[2] + b[2] * k];
const combine = (a: Vec3, ca: number, b: Vec3, cb: number): Vec3 => [
  a[0] * ca + b[0] * cb,
  a[1] * ca + b[1] * cb,
  a[2] * ca + b[2] * cb,
];
const clean = (v: Vec3): Vec3 => [v[0] + 0, v[1] + 0, v[2] + 0];

export const DEFAULT_COLOR = "#16866a";
export const DEFAULT_WIDTH = 3;

/** Turtle state: position plus an orthonormal frame (heading, right, up). */
export class Turtle {
  position: Vec3 = [0, 0, 0];
  heading: Vec3 = [0, 1, 0];
  right: Vec3 = [1, 0, 0];
  up: Vec3 = [0, 0, 1];
  penDown = true;
  color = DEFAULT_COLOR;
  width = DEFAULT_WIDTH;

  /** Moves to a new point; returns the segment drawn, if any. */
  moveTo(to: Vec3): Segment | null {
    const from = this.position;
    this.position = clean(to);
    if (!this.penDown || (from[0] === to[0] && from[1] === to[1] && from[2] === to[2])) return null;
    return { from, to: this.position, color: this.color, width: this.width };
  }

  forwardTarget(d: number): Vec3 {
    return add(this.position, this.heading, d);
  }

  /** Turn right around the up vector. */
  turn(a: number): void {
    const c = cosd(a), s = sind(a);
    [this.heading, this.right] = [combine(this.heading, c, this.right, s), combine(this.right, c, this.heading, -s)];
  }

  /** Pitch the nose towards the up vector, around the right vector. */
  pitch(a: number): void {
    const c = cosd(a), s = sind(a);
    [this.heading, this.up] = [combine(this.heading, c, this.up, s), combine(this.up, c, this.heading, -s)];
  }

  /** Roll the up vector towards the right vector, around the heading. */
  roll(a: number): void {
    const c = cosd(a), s = sind(a);
    [this.up, this.right] = [combine(this.up, c, this.right, s), combine(this.right, c, this.up, -s)];
  }

  resetOrientation(): void {
    this.heading = [0, 1, 0];
    this.right = [1, 0, 0];
    this.up = [0, 0, 1];
  }
}
