import { LogoSyntaxError } from "./errors";

export type TokenKind =
  | "number"
  | "word" // command, procedure or variable name
  | "param" // legacy :name reference
  | "string"
  | "op" // + - * /
  | "cmp" // < > = <= >= <>
  | "lbracket"
  | "rbracket"
  | "lparen"
  | "rparen"
  | "comma"
  | "colon";

export interface Token {
  kind: TokenKind;
  /** Source text; for words and params the lowercase name without the colon. */
  text: string;
  /** Original source text. */
  raw: string;
  value: number;
  line: number;
  column: number;
  /** Whitespace (or start of input / comment) directly before the token. */
  spaceBefore: boolean;
  /** Whitespace (or end of input / comment) directly after the token. */
  spaceAfter: boolean;
  /** First token on its line. */
  lineStart: boolean;
}

export const MAX_SOURCE = 50_000;
export const MAX_TOKENS = 10_000;

const NAME_CHAR = /[\p{L}\p{N}_]/u;
const DIGIT = /[0-9]/;
const SPACE = /\s/;

function lineColAt(source: string, index: number): { line: number; column: number } {
  let line = 1;
  let column = 1;
  for (let i = 0; i < index; i++) {
    if (source[i] === "\n") {
      line++;
      column = 1;
    } else column++;
  }
  return { line, column };
}

export function tokenize(source: string): Token[] {
  if (source.length > MAX_SOURCE) {
    const at = lineColAt(source, MAX_SOURCE);
    throw new LogoSyntaxError(
      `Program jest za długi: ma ${source.length} znaków, a limit to ${MAX_SOURCE}.`,
      at.line,
      at.column,
    );
  }
  const tokens: Token[] = [];
  let i = 0;
  let line = 1;
  let column = 1;
  let gap = true; // whitespace seen since last token
  let lastLine = 0;

  const advance = (n = 1) => {
    for (let k = 0; k < n; k++) {
      if (source[i] === "\n") {
        line++;
        column = 1;
      } else column++;
      i++;
    }
  };

  const push = (kind: TokenKind, raw: string, text: string, value: number, l: number, c: number) => {
    if (tokens.length >= MAX_TOKENS) {
      throw new LogoSyntaxError(`Program ma za dużo elementów (limit to ${MAX_TOKENS}).`, l, c);
    }
    const prev = tokens[tokens.length - 1];
    if (prev) prev.spaceAfter = gap;
    tokens.push({ kind, raw, text, value, line: l, column: c, spaceBefore: gap, spaceAfter: true, lineStart: l !== lastLine });
    lastLine = l;
    gap = false;
  };

  while (i < source.length) {
    const ch = source[i];
    if (SPACE.test(ch)) {
      gap = true;
      advance();
      continue;
    }
    if (ch === ";") {
      while (i < source.length && source[i] !== "\n") advance();
      gap = true;
      continue;
    }
    const l = line;
    const c = column;
    const start = i;

    if (DIGIT.test(ch) || (ch === "." && DIGIT.test(source[i + 1] ?? ""))) {
      while (DIGIT.test(source[i] ?? "")) advance();
      if (source[i] === "." && DIGIT.test(source[i + 1] ?? "")) {
        advance();
        while (DIGIT.test(source[i] ?? "")) advance();
      }
      const next = source[i] ?? "";
      if (next === "." || NAME_CHAR.test(next)) {
        while (i < source.length && (source[i] === "." || NAME_CHAR.test(source[i]))) advance();
        throw new LogoSyntaxError(
          `„${source.slice(start, i)}” nie jest poprawną liczbą. Liczby zapisuj cyframi, np. 80, 12.5 albo .5.`,
          l,
          c,
        );
      }
      const raw = source.slice(start, i);
      push("number", raw, raw, Number(raw), l, c);
      continue;
    }

    if (NAME_CHAR.test(ch)) {
      while (i < source.length && NAME_CHAR.test(source[i])) advance();
      const raw = source.slice(start, i);
      push("word", raw, raw.toLowerCase(), 0, l, c);
      continue;
    }

    if (ch === ":") {
      if (NAME_CHAR.test(source[i + 1] ?? "")) {
        advance();
        while (i < source.length && NAME_CHAR.test(source[i])) advance();
        const raw = source.slice(start, i);
        push("param", raw, raw.slice(1).toLowerCase(), 0, l, c);
      } else {
        advance();
        push("colon", ":", ":", 0, l, c);
      }
      continue;
    }

    if (ch === '"') {
      advance();
      while (i < source.length && source[i] !== '"' && source[i] !== "\n") advance();
      if (source[i] !== '"') {
        throw new LogoSyntaxError("Brakuje zamykającego cudzysłowu. Kolor zapisuj tak: \"#16866a\".", l, c);
      }
      advance();
      const raw = source.slice(start, i);
      push("string", raw, raw.slice(1, -1), 0, l, c);
      continue;
    }

    if ("+-*/".includes(ch)) {
      advance();
      push("op", ch, ch, 0, l, c);
      continue;
    }
    if (ch === "<" || ch === ">" || ch === "=") {
      advance();
      let raw = ch;
      const next = source[i];
      if ((ch === "<" && (next === "=" || next === ">")) || (ch === ">" && next === "=")) {
        raw += next;
        advance();
      }
      push("cmp", raw, raw, 0, l, c);
      continue;
    }
    const single: Record<string, TokenKind> = { "[": "lbracket", "]": "rbracket", "(": "lparen", ")": "rparen", ",": "comma" };
    if (single[ch]) {
      advance();
      push(single[ch], ch, ch, 0, l, c);
      continue;
    }
    throw new LogoSyntaxError(`Nieznany znak „${ch}”.`, l, c);
  }
  const last = tokens[tokens.length - 1];
  if (last) last.spaceAfter = true;
  return tokens;
}
EOF
