import type { LogoError } from "./types";

/** An error found before anything runs: nothing is drawn. */
export class LogoSyntaxError extends Error {
  constructor(message: string, readonly line: number, readonly column: number) {
    super(message);
  }
  toJSON(): LogoError {
    return { message: this.message, line: this.line, column: this.column };
  }
}

/** An error found while running: what was drawn so far is kept. */
export class LogoRuntimeError extends LogoSyntaxError {}
