import type { Expr, Program, Stmt } from "./ast";
import { LogoRuntimeError } from "./errors";
import { Turtle } from "./turtle";
import type { Segment } from "./types";

export class Interpreter {
  readonly turtle = new Turtle();
  segments: Segment[] = [];

  constructor(readonly program: Program) {}

  eval(e: Expr): number {
    switch (e.k) {
      case "num": return e.v;
      case "neg": return -this.eval(e.e);
      case "bin": {
        const a = this.eval(e.a), b = this.eval(e.b);
        switch (e.op) {
          case "+": return a + b;
          case "-": return a - b;
          case "*": return a * b;
          case "/": return a / b;
        }
      }
    }
    throw new Error("unsupported expression");
  }

  exec(stmts: Stmt[]): void {
    for (const s of stmts) this.statement(s);
  }

  statement(s: Stmt): void {
    const t = this.turtle;
    switch (s.k) {
      case "move": {
        const seg = t.moveTo(t.forwardTarget(s.dir * this.eval(s.arg.expr)));
        if (seg) this.segments.push(seg);
        return;
      }
      case "turn": t.turn(s.dir * this.eval(s.arg.expr)); return;
      case "pen": t.penDown = s.down; return;
      case "color": t.color = s.color; return;
      case "width": t.width = this.eval(s.arg.expr); return;
      case "repeat": {
        const n = this.eval(s.count.expr);
        for (let i = 0; i < n; i++) this.exec(s.body);
        return;
      }
    }
    throw new LogoRuntimeError("unsupported", s.at.line, s.at.column);
  }
}
EOF
cat > index.ts <<'EOF'
import { LogoSyntaxError } from "./errors";
import { Interpreter } from "./interpreter";
import { parse } from "./parser";
import type { Mode, RunResult } from "./types";

export type { Mode, RunResult, Segment, LogoError, Vec3 } from "./types";

export function run(source: string, mode: Mode): RunResult {
  let program;
  try {
    program = parse(source, mode);
  } catch (e) {
    if (e instanceof LogoSyntaxError) return { segments: [], error: e.toJSON() };
    throw e;
  }
  const interp = new Interpreter(program);
  try {
    interp.exec(program.main);
  } catch (e) {
    if (e instanceof LogoSyntaxError) return { segments: interp.segments, error: e.toJSON() };
    throw e;
  }
  return { segments: interp.segments, error: null };
}
