import { LogoSyntaxError } from "./errors";
import { Interpreter } from "./interpreter";
import { parse } from "./parser";
import type { Mode, RunResult } from "./types";

export type { Mode, RunResult, Segment, LogoError, Vec3 } from "./types";

export function run(source: string, mode: Mode): RunResult {
  let program;
  try {
    program = parse(source, mode);
  } catch (e) {
    if (e instanceof LogoSyntaxError) return { segments: [], error: e.toJSON() };
    throw e;
  }
  const interp = new Interpreter(program);
  try {
    interp.exec(program.main);
  } catch (e) {
    if (e instanceof LogoSyntaxError) return { segments: interp.segments, error: e.toJSON() };
    throw e;
  }
  return { segments: interp.segments, error: null };
}
