import type { Arg, Cond, Expr, Program, Stmt } from "./ast";
import { isReserved, lookupCommand, REPCOUNT_WORDS } from "./commands";
import { LogoSyntaxError } from "./errors";
import { tokenize, type Token } from "./lexer";
import type { Mode } from "./types";

export const MAX_DEPTH = 32;

interface Scope {
  /** Names readable in expressions here. */
  names: Set<string>;
}

class Parser {
  pos = 0;
  depth = 0;
  repeatDepth = 0;

  constructor(
    readonly tokens: Token[],
    readonly mode: Mode,
    readonly scope: Scope,
  ) {}

  peek(): Token | undefined {
    return this.tokens[this.pos];
  }

  fail(message: string, at: Token): never {
    throw new LogoSyntaxError(message, at.line, at.column);
  }

  /** Statements until the end of input or a closing bracket. */
  block(): Stmt[] {
    const out: Stmt[] = [];
    let t: Token | undefined;
    while ((t = this.peek()) && t.kind !== "rbracket") out.push(this.statement());
    return out;
  }

  /** `[ body ]` following `owner`. */
  body(owner: Token, what: string): { body: Stmt[]; end: Token } {
    const open = this.peek();
    if (!open) this.fail(`Po „${what}” brakuje nawiasu [ z poleceniami.`, owner);
    if (open.kind !== "lbracket") this.fail(`Oczekiwano nawiasu [, a znaleziono „${open.raw}”.`, open);
    if (this.depth >= MAX_DEPTH) {
      this.fail(`Za głębokie zagnieżdżenie nawiasów [ ] (limit to ${MAX_DEPTH}).`, open);
    }
    this.pos++;
    this.depth++;
    const body = this.block();
    this.depth--;
    const end = this.peek();
    if (!end) this.fail("Brakuje nawiasu zamykającego ] dla tego nawiasu [.", open);
    this.pos++;
    return { body, end };
  }

  statement(): Stmt {
    const at = this.tokens[this.pos++];
    if (at.kind !== "word") return this.stray(at);
    const cmd = lookupCommand(at.text);
    switch (cmd) {
      case "forward": return { k: "move", at, dir: 1, arg: this.arg(at) };
      case "back": return { k: "move", at, dir: -1, arg: this.arg(at) };
      case "right": return { k: "turn", at, dir: 1, arg: this.arg(at) };
      case "left": return { k: "turn", at, dir: -1, arg: this.arg(at) };
      case "penup": return { k: "pen", at, down: false };
      case "pendown": return { k: "pen", at, down: true };
      case "color": return { k: "color", at, color: this.tokens[this.pos++].text.toLowerCase() };
      case "width": return { k: "width", at, arg: this.arg(at) };
      case "repeat": {
        const count = this.arg(at);
        this.repeatDepth++;
        const { body, end } = this.body(at, at.raw);
        this.repeatDepth--;
        return { k: "repeat", at, count, body, end };
      }
      case "let": {
        const name = this.tokens[this.pos++];
        return { k: "let", at, name: name.text, arg: this.arg(at) };
      }
      case "if": {
        const cond = this.cond(at);
        const then = this.body(at, at.raw);
        return { k: "if", at, cond, then: then.body, thenEnd: then.end };
      }
      case "ifelse": {
        const cond = this.cond(at);
        const then = this.body(at, at.raw);
        const other = this.body(at, at.raw);
        return { k: "if", at, cond, then: then.body, thenEnd: then.end, else: other.body, elseEnd: other.end };
      }
    }
    return this.fail(`Nieznane polecenie „${at.raw}”.`, at);
  }

  stray(at: Token): never {
    return this.fail(`Oczekiwano polecenia, a znaleziono „${at.raw}”.`, at);
  }

  arg(command: Token): Arg {
    const at = this.peek();
    if (!at) this.fail(`Polecenie „${command.raw}” wymaga argumentu.`, command);
    return { at, expr: this.expr() };
  }

  cond(command: Token): Cond {
    const { at, expr: a } = this.arg(command);
    const op = this.peek();
    if (!op || op.kind !== "cmp") {
      this.fail("Oczekiwano porównania: <, >, =, <=, >= albo <>.", op ?? command);
    }
    this.pos++;
    const b = this.expr();
    return { at, op: op.text as Cond["op"], a, b };
  }

  /** Binary operator directly following an operand, honouring the whitespace rule. */
  binaryOp(ops: string): Token | undefined {
    const t = this.peek();
    if (!t || t.kind !== "op" || !ops.includes(t.text)) return undefined;
    if (t.spaceBefore !== t.spaceAfter) return undefined;
    return t;
  }

  expr(): Expr {
    let a = this.term();
    let op: Token | undefined;
    while ((op = this.binaryOp("+-"))) {
      this.pos++;
      a = { k: "bin", op: op.text as "+" | "-", a, b: this.term() };
    }
    return a;
  }

  term(): Expr {
    let a = this.unary();
    let op: Token | undefined;
    while ((op = this.binaryOp("*/"))) {
      this.pos++;
      a = { k: "bin", op: op.text as "*" | "/", a, b: this.unary() };
    }
    return a;
  }

  unary(): Expr {
    const t = this.peek();
    if (t && t.kind === "op" && (t.text === "-" || t.text === "+")) {
      this.pos++;
      const e = this.unary();
      return t.text === "-" ? { k: "neg", e } : e;
    }
    return this.primary();
  }

  primary(): Expr {
    const t = this.tokens[this.pos++];
    if (t.kind === "number") return { k: "num", v: t.value };
    if (t.kind === "lparen") {
      const e = this.expr();
      this.pos++;
      return e;
    }
    if (t.kind === "word" && REPCOUNT_WORDS.includes(t.text)) return { k: "repcount" };
    if ((t.kind === "word" || t.kind === "param") && this.scope.names.has(t.text)) return { k: "var", name: t.text };
    return this.fail(`Oczekiwano wartości, a znaleziono „${t.raw}”.`, t);
  }
}

/** Names assigned by `niech` anywhere in a token stream. */
function assignedNames(tokens: Token[]): Set<string> {
  const names = new Set<string>();
  for (let i = 0; i < tokens.length - 1; i++) {
    if (tokens[i].kind === "word" && lookupCommand(tokens[i].text) === "let" && tokens[i + 1].kind === "word") {
      const name = tokens[i + 1].text;
      if (!isReserved(name)) names.add(name);
    }
  }
  return names;
}

export function parse(source: string, mode: Mode): Program {
  const tokens = tokenize(source);
  const p = new Parser(tokens, mode, { names: assignedNames(tokens) });
  return { main: p.block(), procedures: new Map() };
}
