import type { Arg, Cond, Expr, Program, Stmt } from "./ast";
import { LogoRuntimeError } from "./errors";
import { Turtle } from "./turtle";
import type { Segment } from "./types";

interface Frame {
  locals: Map<string, number> | null;
  repeats: number[];
}

export class Interpreter {
  readonly turtle = new Turtle();
  segments: Segment[] = [];
  readonly globals = new Map<string, number>();
  frame: Frame = { locals: null, repeats: [] };

  constructor(readonly program: Program) {}

  value(arg: Arg): number {
    return this.eval(arg.expr);
  }

  eval(e: Expr): number {
    switch (e.k) {
      case "num": return e.v;
      case "neg": return -this.eval(e.e);
      case "repcount": return this.frame.repeats[this.frame.repeats.length - 1];
      case "var": {
        const v = this.frame.locals?.get(e.name) ?? this.globals.get(e.name);
        return v!;
      }
      case "bin": {
        const a = this.eval(e.a), b = this.eval(e.b);
        switch (e.op) {
          case "+": return a + b;
          case "-": return a - b;
          case "*": return a * b;
          case "/": return a / b;
        }
      }
    }
  }

  test(c: Cond): boolean {
    const a = this.eval(c.a), b = this.eval(c.b);
    switch (c.op) {
      case "<": return a < b;
      case ">": return a > b;
      case "=": return a === b;
      case "<=": return a <= b;
      case ">=": return a >= b;
      case "<>": return a !== b;
    }
  }

  exec(stmts: Stmt[]): void {
    for (const s of stmts) this.statement(s);
  }

  statement(s: Stmt): void {
    const t = this.turtle;
    switch (s.k) {
      case "move": {
        const seg = t.moveTo(t.forwardTarget(s.dir * this.value(s.arg)));
        if (seg) this.segments.push(seg);
        return;
      }
      case "turn": t.turn(s.dir * this.value(s.arg)); return;
      case "pen": t.penDown = s.down; return;
      case "color": t.color = s.color; return;
      case "width": t.width = this.value(s.arg); return;
      case "let": (this.frame.locals ?? this.globals).set(s.name, this.value(s.arg)); return;
      case "if":
        if (this.test(s.cond)) this.exec(s.then);
        else if (s.else) this.exec(s.else);
        return;
      case "repeat": {
        const n = this.value(s.count);
        for (let i = 1; i <= n; i++) {
          this.frame.repeats.push(i);
          this.exec(s.body);
          this.frame.repeats.pop();
        }
        return;
      }
    }
    throw new LogoRuntimeError("unsupported", s.at.line, s.at.column);
  }
}
