import type { Expr } from "./ast";

export const LIMITS = {
  source: 50_000,
  tokens: 10_000,
  depth: 32,
  frames: 32,
  operations: 10_000,
  segments: 10_000,
  coordinate: 100_000,
  repeat: 10_000,
  width: [1, 12] as const,
};

/** Returns a Polish complaint when `v` is not an integer in [min, max]. */
export function integerProblem(v: number, min: number, max: number, what: string): string | null {
  if (!Number.isInteger(v)) return `${what} musi być liczbą całkowitą, a wynosi ${fmt(v)}.`;
  if (v < min || v > max) return `${what} musi być z zakresu ${min}–${max}, a wynosi ${fmt(v)}.`;
  return null;
}

export const widthProblem = (v: number) => integerProblem(v, LIMITS.width[0], LIMITS.width[1], "Grubość");
export const countProblem = (v: number) => integerProblem(v, 0, LIMITS.repeat, "Liczba powtórzeń");

function fmt(v: number): string {
  return Number.isFinite(v) ? String(Math.round(v * 1e6) / 1e6).replace(".", ",") : "nieskończoność";
}

/** True when the expression uses no names (and no nrpowt). */
export function isConstant(e: Expr): boolean {
  switch (e.k) {
    case "num": return true;
    case "var":
    case "repcount": return false;
    case "neg": return isConstant(e.e);
    case "bin": return isConstant(e.a) && isConstant(e.b);
  }
}
EOF
