    expect(run("oto f\njuż\noto F\njuż", "2d").error).toMatchObject({ line: 3, column: 5 });
  });
  test("już must stand alone on its line", () => {
    expect(run("oto f\n np 1 już", "2d").error).toMatchObject({ line: 2, column: 7 });
  });
  test("a variable may not take a procedure's or a command's name", () => {
    expect(run("oto f\njuż\nniech f 1", "2d").error).toMatchObject({ line: 3, column: 7 });
    expect(run("niech np 1", "2d").error).toMatchObject({ line: 1, column: 7 });
  });
