describe("interpreter: 3D orientation", () => {
  const end = (src: string) => {
    const r = run(src, "3d");
    expect(r.error).toBeNull();
    return r.segments[r.segments.length - 1].to;
  };
  test("gora 90 heads along the former up vector, dol the other way", () => {
    expect(end("gora 90 np 10")).toEqual([0, 0, 10]);
    expect(end("dol 90 np 10")).toEqual([0, 0, -10]);
  });
  test("after gora 90 the up vector is the former backward direction", () => {
    // heading +Z, up -Y: a right turn keeps the right vector +X as the new heading
    expect(end("gora 90 pw 90 np 10")).toEqual([10, 0, 0]);
    // pitching again heads along the current up (-Y)
    expect(end("gora 90 gora 90 np 10")).toEqual([0, -10, 0]);
  });
  test("pp 90 makes up the former right and right the former down", () => {
    expect(end("pp 90 np 10")).toEqual([0, 10, 0]);
    expect(end("pp 90 pw 90 np 10")).toEqual([0, 0, -10]);
    expect(end("pp 90 gora 90 np 10")).toEqual([10, 0, 0]);
    expect(end("pl 90 gora 90 np 10")).toEqual([-10, 0, 0]);
  });
