describe("interpreter: limits", () => {
  test("10,000 operations are allowed, the next one is an error that keeps the drawing", () => {
    // 1 (repeat) + n × (1 command + 1 finished iteration)
    expect(run("powtorz 4999 [np 1]", "2d").error).toBeNull();
    const over = run("powtorz 5000 [np 1]", "2d");
    expect(over.error).not.toBeNull();
    expect(over.segments).toHaveLength(5000);
  });
  test("conditionals, their bodies and calls count as operations", () => {
    // 1 + n × (if + command + finished body + finished iteration)
    expect(run("powtorz 2499 [jeśli 1 = 1 [pw 1]]", "2d").error).toBeNull();
    expect(run("powtorz 2500 [jeśli 1 = 1 [pw 1]]", "2d").error).not.toBeNull();
    // 1 + n × (call + command + finished call + finished iteration)
    const def = "oto f\n pw 1\njuż\n";
    expect(run(def + "powtorz 2499 [f]", "2d").error).toBeNull();
    expect(run(def + "powtorz 2500 [f]", "2d").error).not.toBeNull();
    // niech counts: 1 + n × 2
    expect(run("powtorz 4999 [niech a 1]", "2d").error).toBeNull();
    expect(run("powtorz 5000 [niech a 1]", "2d").error).not.toBeNull();
  });
  test("32 active call and repeat frames are allowed, the 33rd is an error at the call", () => {
    const def = "oto f ma: n\n jeśli n > 1 [f n - 1]\njuż\n";
    expect(run(def + "f 32", "2d").error).toBeNull();
    expect(run(def + "np 5\nf 33", "2d")).toMatchObject({ segments: [{}], error: { line: 2, column: 15 } });
    const r = run("oto f\n np 1\n f\njuż\nf", "2d");
    expect(r.error).toMatchObject({ line: 3, column: 2 });
    expect(r.segments).toHaveLength(32);
  });
  test("32 nested repeats at top level are within the limits", () => {
    const src = "powtorz 1 [".repeat(32) + "np 1" + "]".repeat(32);
    expect(run(src, "2d")).toMatchObject({ error: null, segments: [{}] });
    const deeper = "powtorz 1 [".repeat(33) + "np 1" + "]".repeat(33);
    expect(run(deeper, "2d")).toMatchObject({ segments: [], error: { line: 1, column: 32 * 11 + 9 } });
  });
  test("coordinates must stay within ±100,000", () => {
    expect(run("pod np 100000 opu np 0", "2d").error).toBeNull();
    const r = run("np 50\nnp 99951", "2d");
    expect(r).toMatchObject({ segments: [{}], error: { line: 2, column: 1 } });
  });
  test("source length and token count limits", () => {
    expect(run("pw 1 ".repeat(5000), "2d").error).toBeNull();
    expect(run("pw 1 ".repeat(5000) + "pw", "2d").error).toMatchObject({ line: 1, column: 25001 });
    const long = ";" + "x".repeat(50_000);
    expect(run(long, "2d").error).not.toBeNull();
    expect(run(";" + "x".repeat(49_999), "2d").error).toBeNull();
  });
});
EOF
