cat > tests/examples.test.ts <<'EOF'
import { describe, expect, test } from "bun:test";
import { run } from "../src/lang";
import { standardExamples } from "../src/app/examples";

const byName = (name: string) => {
  const e = standardExamples.find((x) => x.name === name);
  if (!e) throw new Error(`missing example ${name}`);
  return e;
};

const expectedCounts: Record<string, [mode: "2d" | "3d", segments: number]> = {
  kwadrat: ["2d", 4],
  gwiazda: ["2d", 5],
  rozeta: ["2d", 48],
  spirala: ["2d", 90],
  wielokaty: ["2d", 42],
  drzewo: ["2d", 255],
  sniezynka: ["2d", 768],
  schody: ["3d", 12],
  szescian: ["3d", 17],
  pierscien: ["3d", 36],
  kula: ["3d", 432],
  helisa: ["3d", 240],
  drzewo3d: ["3d", 121],
};

describe("standard programs", () => {
  test("all thirteen ship under their names and modes", () => {
    expect(standardExamples.map((e) => [e.name, e.mode])).toEqual(
      Object.entries(expectedCounts).map(([name, [mode]]) => [name, mode]),
    );
  });

  for (const [name, [mode, count]] of Object.entries(expectedCounts)) {
    test(`${name} runs without error and draws ${count} segments`, () => {
      const r = run(byName(name).source, mode);
      expect(r.error).toBeNull();
      expect(r.segments).toHaveLength(count);
    });
  }

  test("kwadrat source is shipped byte for byte", () => {
    expect(byName("kwadrat").source).toBe(
      '; Cztery boki, cztery skręty.\nkolor "#16866a"\ngrubosc 3\npowtorz 4 [\n  np 120\n  pw 90\n]\n',
    );
  });

  test("flat programs draw identical coordinates in 2D and 3D", () => {
    for (const e of standardExamples.filter((x) => x.mode === "2d")) {
      expect(run(e.source, "3d")).toEqual(run(e.source, "2d"));
    }
  });

  test("spirala alternates green and orange", () => {
    const colors = run(byName("spirala").source, "2d").segments.slice(0, 3).map((s) => s.color);
    expect(colors).toEqual(["#16866a", "#c1763d", "#16866a"]);
  });

  test("szescian's corners are the eight vertices of a 100-unit cube", () => {
    const pts = new Set<string>();
    for (const s of run(byName("szescian").source, "3d").segments)
      for (const p of [s.from, s.to]) pts.add(p.map((c) => Math.round(c)).join(","));
    expect([...pts].sort()).toEqual(
      ["0,0,0", "0,0,100", "0,100,0", "0,100,100", "100,0,0", "100,0,100", "100,100,0", "100,100,100"].sort(),
    );
  });

  test("pierscien lies in a plane tilted 30° about the X axis and closes", () => {
    const segs = run(byName("pierscien").source, "3d").segments;
    const c = Math.cos(Math.PI / 6), s = Math.sin(Math.PI / 6);
    for (const seg of segs) expect(Math.abs(c * seg.to[2] - s * seg.to[1])).toBeLessThan(1e-9);
    for (const k of segs[35].to) expect(Math.abs(k)).toBeLessThan(1e-9);
  });
});
EOF
bun test tests 2>&1 | grep -E "^\s*[0-9]+ (pass|fail)|\(fail\)|rror" | head -5

