git add -A && git commit -qm "Interpreter for the Logomocja dialect with tests and standard programs

Co-Authored-By: Claude Opus 5.5 <noreply@anthropic.com>" && cat >> tests/interpreter.test.ts <<'EOF'

describe("interpreter: lexical rules", () => {
  test("only unsigned decimal literals are numbers", () => {
    for (const bad of ["np 1e3", "np 0x10", "np NaN", "np Infinity", "np 1.2.3"]) {
      const r = run(bad, "2d");
      expect(r.segments).toEqual([]);
      expect(r.error).toMatchObject({ line: 1, column: 4 });
    }
  });
  test("comments run to the end of the line; keywords ignore case; aliases are equivalent", () => {
    const r = run("FD 10 ; np 99\nNaprzód 10 naprzod 10 forward 10\nPRAWO 90 rt 90 Lewo 180 lt 90 wstecz 5 back 5", "2d");
    expect(r.error).toBeNull();
    expect(r.segments.map((s) => s.to)).toEqual([
      [0, 10, 0],
      [0, 20, 0],
      [0, 30, 0],
      [0, 40, 0],
      [0, 35, 0],
      [0, 30, 0],
    ]);
  });
  test("accented and English spellings of every command work", () => {
    const src = 'podnieś opuść penup pendown pu pd kolor "#000000" color "#FFFFFF" grubość 2 width 1 powtórz 1 [repeat 1 [fd repcount]] jesli 1 = 1 [] jezeli 1 = 1 [] [] if 1 = 1 [] ifelse 1 = 2 [] [] let a 1 niech b 2 czysc cs clearscreen czyść home dom';
    expect(run(src, "2d").error).toBeNull();
    expect(run("góra 1 gora 1 dół 1 dol 1 pitchup 1 pitchdown 1 przechylprawo 1 rr 1 przechyllewo 1 rl 1 rollright 1 rollleft 1", "3d").error).toBeNull();
  });
  test("comparisons are exact", () => {
    expect(run("jeśli 0.1 + 0.2 = 0.3 [np 10]", "2d").segments).toEqual([]);
    const r = run("jeśli 1 <= 1 [np 1] jeśli 1 >= 2 [np 2] jeśli 1 <> 2 [np 3] jeżeli 2 < 1 [np 4] [np 5]", "2d");
    expect(r.segments.map((s) => s.to[1] - s.from[1])).toEqual([1, 3, 5]);
  });
  test("negative and decimal angles turn the other way / by fractions", () => {
    const r = run("pw -90 np 10", "2d");
    expect(r.segments[0].to).toEqual([-10, 0, 0]);
  });
  test("nrpowt in a procedure body outside a repeat is a parse error even if called from a repeat", () => {
    const r = run("oto f\n np nrpowt\njuż\npowtorz 3 [f]", "2d");
    expect(r).toMatchObject({ segments: [], error: { line: 2, column: 5 } });
  });
  test("a colour literal must be closed", () => {
    expect(run('kolor "#16866a', "2d").error).toMatchObject({ line: 1, column: 7 });
  });
  test("an unknown command is reported where it stands", () => {
    const r = run("np 10\n  skacz 5", "2d");
    expect(r).toMatchObject({ segments: [], error: { line: 2, column: 3 } });
    expect(r.error!.message).toContain("skacz");
  });
});
EOF
