import type { Scheduler, KeyValueStore } from "../src/app/studio";

/** A scheduler the test advances by hand, one animation frame at a time. */
export function manualScheduler() {
  let queue: (() => void)[] = [];
  const scheduler: Scheduler = {
    request(cb) {
      queue.push(cb);
      return queue.length;
    },
    cancel() {
      queue = [];
    },
  };
  return {
    scheduler,
    /** Runs one frame; returns false when nothing was scheduled. */
    frame(): boolean {
      const q = queue;
      queue = [];
      q.forEach((cb) => cb());
      return q.length > 0;
    },
    /** Runs frames until idle; returns how many ran. */
    flush(max = 100_000): number {
      let n = 0;
      while (n < max && this.frame()) n++;
      return n;
    },
    get pending() {
      return queue.length;
    },
  };
}

export function memoryStore(initial: Record<string, string> = {}): KeyValueStore & { data: Record<string, string> } {
  const data = { ...initial };
  return {
    data,
    getItem: (k) => (k in data ? data[k] : null),
    setItem: (k, v) => {
      data[k] = v;
    },
    removeItem: (k) => {
      delete data[k];
    },
  };
}
EOF
cat > tests/controls.test.ts <<'EOF'
import { describe, expect, test } from "bun:test";
import { run } from "../src/lang";
import { createStudio } from "../src/app/studio";
import { manualScheduler, memoryStore } from "./helpers";

const SQUARE = "powtorz 4 [\n  np 100\n  pw 90\n]";

function setup(source = SQUARE) {
  const clock = manualScheduler();
  const studio = createStudio({ storage: memoryStore(), scheduler: clock.scheduler });
  studio.setMode("2d");
  studio.setSource(source);
  return { studio, clock };
}

describe("execution controls: run", () => {
  test("an animated run draws progressively and ends with the interpreter's drawing", () => {
    const { studio, clock } = setup();
    studio.setSpeed(1);
    studio.run();
    expect(studio.state.status).toBe("running");
    clock.frame();
    const partial = studio.state.segments.length;
    expect(partial).toBeLessThan(4);
    const frames = clock.flush();
    expect(frames).toBeGreaterThan(1);
    expect(studio.state.status).toBe("done");
    expect(studio.state.segments).toEqual(run(SQUARE, "2d").segments);
  });
});
EOF
