import { LogoSyntaxError } from "./errors";
import { Interpreter } from "./interpreter";
import type { Token } from "./lexer";
import { parse } from "./parser";
import type { LogoError, Mode, RunResult, Segment, TurtleState } from "./types";

export type { Mode, RunResult, Segment, LogoError, Vec3, TurtleState } from "./types";
export { LIMITS } from "./limits";

export interface StepResult {
  /** True when the program has finished (normally, by stop, or with an error). */
  done: boolean;
  /** Position of the command just executed, if any. */
  line: number | null;
  column: number | null;
}

/** A program being executed one command at a time. */
export interface Execution {
  readonly mode: Mode;
  /** Executes the next command. */
  step(): StepResult;
  /** Runs to the end. */
  finish(): void;
  readonly done: boolean;
  readonly segments: Segment[];
  readonly turtle: TurtleState;
  readonly error: LogoError | null;
}

/** Validates the whole program; returns an execution or the parse-time error. */
export function start(source: string, mode: Mode): Execution | { error: LogoError } {
  let interp: Interpreter;
  try {
    interp = new Interpreter(parse(source, mode));
  } catch (e) {
    if (e instanceof LogoSyntaxError) return { error: e.toJSON() };
    throw e;
  }
  const gen = interp.exec(interp.program.main);
  let done = false;
  let error: LogoError | null = null;
  const exec: Execution = {
    mode,
    step() {
      if (done) return { done, line: null, column: null };
      let at: Token | null = null;
      try {
        const r = gen.next();
        if (r.done) done = true;
        else at = r.value;
      } catch (e) {
        if (!(e instanceof LogoSyntaxError)) throw e;
        error = e.toJSON();
        done = true;
        return { done, line: error.line, column: error.column };
      }
      return { done, line: at?.line ?? null, column: at?.column ?? null };
    },
    finish() {
      while (!done) exec.step();
    },
    get done() {
      return done;
    },
    get segments() {
      return interp.segments;
    },
    get turtle() {
      return interp.turtle.snapshot();
    },
    get error() {
      return error;
    },
  };
  return exec;
}

export function isExecution(x: Execution | { error: LogoError }): x is Execution {
  return "step" in x;
}

/** Interprets a whole program: the testing hook's `run`. */
export function run(source: string, mode: Mode): RunResult {
  const exec = start(source, mode);
  if (!isExecution(exec)) return { segments: [], error: exec.error };
  exec.finish();
  return { segments: exec.segments.slice(), error: exec.error };
}
