import { isExecution, start, type Execution, type LogoError, type Mode, type RunResult, type Segment, type TurtleState } from "../lang";

/** Minimal storage interface (window.localStorage satisfies it). */
export interface KeyValueStore {
  getItem(key: string): string | null;
  setItem(key: string, value: string): void;
  removeItem(key: string): void;
}

/** Animation clock (window.requestAnimationFrame satisfies it). */
export interface Scheduler {
  request(cb: () => void): number;
  cancel(handle: number): void;
}

export type Status = "idle" | "running" | "paused" | "done" | "error" | "stopped";

export interface StudioState {
  mode: Mode;
  source: string;
  status: Status;
  segments: Segment[];
  turtle: TurtleState;
  error: LogoError | null;
  /** Line of the command just executed while running or stepping. */
  line: number | null;
  /** 0..1: how far the last drawn segment has grown (animation of slow speeds). */
  glide: number;
  speed: number;
  notice: string | null;
}

export interface StudioOptions {
  storage: KeyValueStore;
  scheduler: Scheduler;
}

/** Commands per frame (≥1) or frames per command (<1 as 1/n). */
const SPEED_TABLE: Record<number, { perFrame: number; framesPer: number }> = {
  1: { perFrame: 1, framesPer: 30 },
  2: { perFrame: 1, framesPer: 14 },
  3: { perFrame: 1, framesPer: 6 },
  4: { perFrame: 1, framesPer: 3 },
  5: { perFrame: 1, framesPer: 1 },
  6: { perFrame: 3, framesPer: 1 },
  7: { perFrame: 10, framesPer: 1 },
  8: { perFrame: 40, framesPer: 1 },
  9: { perFrame: 200, framesPer: 1 },
  10: { perFrame: Infinity, framesPer: 1 },
};
export const MIN_SPEED = 1;
export const MAX_SPEED = 10;

export function initialTurtle(): TurtleState {
  return {
    position: [0, 0, 0],
    heading: [0, 1, 0],
    right: [1, 0, 0],
    up: [0, 0, 1],
    penDown: true,
    color: "#16866a",
    width: 3,
  };
}

export type Studio = ReturnType<typeof createStudio>;

export function createStudio(options: StudioOptions) {
  const { scheduler } = options;
  const listeners = new Set<(s: StudioState) => void>();
  let exec: Execution | null = null;
  let handle: number | null = null;
  let waitFrames = 0;
  let waited = 0;

  const state: StudioState = {
    mode: "2d",
    source: "",
    status: "idle",
    segments: [],
    turtle: initialTurtle(),
    error: null,
    line: null,
    glide: 1,
    speed: 6,
    notice: null,
  };

  const emit = () => listeners.forEach((l) => l(state));

  const cancelFrame = () => {
    if (handle !== null) scheduler.cancel(handle);
    handle = null;
  };

  const sync = () => {
    if (!exec) return;
    state.segments = exec.segments.slice();
    state.turtle = exec.turtle;
    if (exec.done) {
      state.error = exec.error;
      state.status = exec.error ? "error" : "done";
      if (!exec.error) state.line = null;
    }
  };

  /** Executes one command; returns true when it drew something. */
  const stepOnce = (): boolean => {
    if (!exec) return false;
    const before = exec.segments.length;
    const r = exec.step();
    state.line = r.line;
    return exec.segments.length !== before;
  };

  const frame = () => {
    handle = null;
    if (!exec || state.status !== "running") return;
    const { perFrame, framesPer } = SPEED_TABLE[state.speed];
    if (framesPer > 1) {
      if (waited < waitFrames) {
        waited++;
        state.glide = waited / waitFrames;
      } else {
        const drew = stepOnce();
        waitFrames = framesPer - 1;
        waited = 0;
        state.glide = drew && waitFrames > 0 ? 0 : 1;
      }
    } else {
      state.glide = 1;
      for (let i = 0; i < perFrame && !exec.done; i++) stepOnce();
    }
    sync();
    if (state.status === "running") handle = scheduler.request(frame);
    emit();
  };

  /** Validates and prepares a fresh execution; false on a parse error. */
  const begin = (): boolean => {
    cancelFrame();
    state.notice = null;
    state.line = null;
    state.glide = 1;
    waitFrames = 0;
    waited = 0;
    const e = start(state.source, state.mode);
    if (!isExecution(e)) {
      exec = null;
      state.segments = [];
      state.turtle = initialTurtle();
      state.error = e.error;
      state.status = "error";
      return false;
    }
    exec = e;
    state.segments = [];
    state.turtle = e.turtle;
    state.error = null;
    return true;
  };

  const studio = {
    get state(): Readonly<StudioState> {
      return state;
    },
    subscribe(fn: (s: StudioState) => void): () => void {
      listeners.add(fn);
      return () => listeners.delete(fn);
    },
    setMode(mode: Mode) {
      state.mode = mode;
      emit();
    },
    setSource(source: string) {
      state.source = source;
      emit();
    },
    setSpeed(speed: number) {
      state.speed = Math.min(MAX_SPEED, Math.max(MIN_SPEED, Math.round(speed)));
      emit();
    },
    /** Runs the program with animation at the current speed. */
    run() {
      if (begin()) {
        state.status = "running";
        handle = scheduler.request(frame);
      }
      emit();
    },
    /** Runs the program to the end at once. */
    runInstant(): RunResult {
      if (begin()) {
        exec!.finish();
        sync();
      }
      emit();
      return { segments: state.segments.slice(), error: state.error };
    },
  };
  return studio;
}
