import type { Mode } from "../lang";

/** Hash route that carries a shared program. */
export const PROGRAM_ROUTE = "#/program";

function toBase64Url(text: string): string {
  const bytes = new TextEncoder().encode(text);
  let bin = "";
  for (let i = 0; i < bytes.length; i += 0x8000) bin += String.fromCharCode(...bytes.subarray(i, i + 0x8000));
  return btoa(bin).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

function fromBase64Url(data: string): string | null {
  if (!/^[A-Za-z0-9_-]*$/.test(data)) return null;
  try {
    const bin = atob(data.replace(/-/g, "+").replace(/_/g, "/"));
    const bytes = Uint8Array.from(bin, (c) => c.charCodeAt(0));
    return new TextDecoder("utf-8", { fatal: true }).decode(bytes);
  } catch {
    return null;
  }
}

/** The hash part (`#/program?…`) encoding a program and its mode. */
export function encodeShareHash(source: string, mode: Mode): string {
  return `${PROGRAM_ROUTE}?tryb=${mode}&kod=${toBase64Url(source)}`;
}

/** Decodes a full URL or just its hash; null when it carries no valid program. */
export function decodeShare(urlOrHash: string): { source: string; mode: Mode } | null {
  const hashAt = urlOrHash.indexOf("#");
  const hash = hashAt >= 0 ? urlOrHash.slice(hashAt) : urlOrHash;
  if (!hash.startsWith(PROGRAM_ROUTE + "?")) return null;
  const params = new URLSearchParams(hash.slice(PROGRAM_ROUTE.length + 1));
  const mode = params.get("tryb");
  const data = params.get("kod");
  if ((mode !== "2d" && mode !== "3d") || data === null) return null;
  const source = fromBase64Url(data);
  return source === null ? null : { source, mode };
}
