import { createChallengeBook } from "../src/app/challenges";

describe("product flows: challenges", () => {
  test("there are at least five challenges, each with a task, a mode and a target drawing", () => {
    const book = createChallengeBook(memoryStore());
    expect(book.list.length).toBeGreaterThanOrEqual(5);
    for (const c of book.list) {
      expect(c.title.length).toBeGreaterThan(0);
      expect(c.task.length).toBeGreaterThan(0);
      expect(c.target.length).toBeGreaterThan(0);
      expect(["2d", "3d"]).toContain(c.mode);
    }
  });

  test("a different program that draws the same triangle passes", () => {
    const book = createChallengeBook(memoryStore());
    // the reference goes clockwise; this goes the other way round and splits a side in two
    const r = book.check("trojkat", "pw 60 np 100 lw 120 np 50 np 50 lw 120 np 100");
    expect(r).toMatchObject({ passed: true });
  });

  test("a wrong drawing fails with a reason", () => {
    const book = createChallengeBook(memoryStore());
    const short = book.check("trojkat", "powtorz 3 [np 90 pw 120]");
    expect(short.passed).toBe(false);
    expect(short.reason.length).toBeGreaterThan(0);
    const extra = book.check("trojkat", "powtorz 3 [np 100 pw 120] pw 90 np 40");
    expect(extra.passed).toBe(false);
    expect(extra.reason).not.toBe(short.reason);
  });

  test("a program with an error or no drawing fails and says so", () => {
    const book = createChallengeBook(memoryStore());
    const err = book.check("trojkat", "powtorz 3 [np 100 pw 120");
    expect(err.passed).toBe(false);
    expect(err.reason).toContain("1");
    expect(book.check("trojkat", "pw 90").passed).toBe(false);
  });

  test("a challenge that requires repeat rejects a correct drawing written without it", () => {
    const book = createChallengeBook(memoryStore());
    const hex = book.list.find((c) => c.id === "szesciokat")!;
    expect(hex.requires).toContain("repeat");
    const longhand = Array.from({ length: 6 }, () => "np 60 pw 60").join(" ");
    expect(book.check("szesciokat", longhand)).toMatchObject({ passed: false });
    expect(book.check("szesciokat", "powtorz 6 [np 60 pw 60]")).toMatchObject({ passed: true });
  });

  test("every challenge accepts its own model solution", () => {
    const book = createChallengeBook(memoryStore());
    for (const c of book.list) expect(book.check(c.id, c.solution)).toMatchObject({ passed: true });
  });

  test("progress and attempts persist across a reload", () => {
    const storage = memoryStore();
    const book = createChallengeBook(storage);
    book.check("trojkat", "powtorz 3 [np 100 pw 120]");
    book.saveAttempt("prostokat", "np 80");
    const again = createChallengeBook(storage);
    expect(again.progress().trojkat).toMatchObject({ passed: true });
    expect(again.attempt("prostokat")).toBe("np 80");
    expect(again.attempt("trojkat")).toBe("powtorz 3 [np 100 pw 120]");
  });

  test("a pass is not taken back by a later failed attempt", () => {
    const storage = memoryStore();
    const book = createChallengeBook(storage);
    book.check("trojkat", "powtorz 3 [np 100 pw 120]");
    book.check("trojkat", "np 1");
    expect(createChallengeBook(storage).progress().trojkat).toMatchObject({ passed: true });
  });
});
EOF
