  const wrap = document.createElement("span");
  wrap.innerHTML = `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true" focusable="false" ${extra}>${paths}</svg>`;
  return wrap.firstElementChild as SVGSVGElement;
}

