function clamp(v: number, lo: number, hi: number): number {
  return Math.min(hi, Math.max(lo, v));
}

/** Stroke widths grow a little with zoom but stay readable. */
function lineScale(scale: number): number {
  return clamp(Math.sqrt(scale), 0.6, 3);
}
