import type { Segment, TurtleState, Vec3 } from "../lang";

export interface Bounds {
  min: Vec3;
  max: Vec3;
}

/** Bounding box of the drawing, the origin and (optionally) the turtle. */
export function drawingBounds(segments: Segment[], turtle?: TurtleState): Bounds {
  const min: Vec3 = [0, 0, 0];
  const max: Vec3 = [0, 0, 0];
  const add = (p: Vec3) => {
    for (let i = 0; i < 3; i++) {
      if (p[i] < min[i]) min[i] = p[i];
      if (p[i] > max[i]) max[i] = p[i];
    }
  };
  for (const s of segments) {
    add(s.from);
    add(s.to);
  }
  if (turtle) add(turtle.position);
  return { min, max };
}

export const lerp = (a: Vec3, b: Vec3, t: number): Vec3 => [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t];

/** Applies the glide animation: the last segment grows and the turtle rides on its tip. */
export function animated(segments: Segment[], turtle: TurtleState, glide: number): { segments: Segment[]; turtle: TurtleState } {
  if (glide >= 1 || segments.length === 0) return { segments, turtle };
  const last = segments[segments.length - 1];
  const tip = lerp(last.from, last.to, glide);
  return {
    segments: [...segments.slice(0, -1), { ...last, to: tip }],
    turtle: { ...turtle, position: tip },
  };
}

/** Reads a CSS custom property from the document. */
export function cssVar(name: string, fallback: string): string {
  const v = getComputedStyle(document.documentElement).getPropertyValue(name).trim();
  return v || fallback;
}
