  private drawSegments(ctx: CanvasRenderingContext2D, segs: Segment[], cam: Camera, w: number, hgt: number, k: number): void {
    ctx.lineCap = "round";
    ctx.lineJoin = "round";
    // batch consecutive segments that share a style
    let i = 0;
    while (i < segs.length) {
      const { color, width } = segs[i];
      ctx.strokeStyle = color;
      ctx.lineWidth = width * k;
      ctx.beginPath();
      let last: [number, number] | null = null;
      while (i < segs.length && segs[i].color === color && segs[i].width === width) {
        const s = segs[i];
        const a = this.toScreen(s.from[0], s.from[1], cam, w, hgt);
        const b = this.toScreen(s.to[0], s.to[1], cam, w, hgt);
        if (!last || last[0] !== a[0] || last[1] !== a[1]) ctx.moveTo(a[0], a[1]);
        ctx.lineTo(b[0], b[1]);
        last = b;
        i++;
      }
      ctx.stroke();
    }
  }

  private drawTurtle(ctx: CanvasRenderingContext2D, t: TurtleState): void {
    const [x, y] = this.toScreen(t.position[0], t.position[1]);
    const angle = Math.atan2(t.heading[0], t.heading[1]); // clockwise from screen-up
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(angle);
    const s = 11;
    ctx.beginPath();
    ctx.moveTo(0, -s * 1.3);
    ctx.lineTo(s * 0.85, s * 0.8);
    ctx.lineTo(0, s * 0.35);
    ctx.lineTo(-s * 0.85, s * 0.8);
    ctx.closePath();
    ctx.lineWidth = 2;
    ctx.strokeStyle = cssVar("--turtle-outline", "#1f2a27");
    ctx.fillStyle = t.penDown ? t.color : cssVar("--paper", "#fbf8f1");
    ctx.fill();
    ctx.stroke();
    ctx.restore();
  }

  private bindInput(): void {
    const c = this.canvas;
    c.addEventListener("pointerdown", (e) => {
      c.setPointerCapture(e.pointerId);
      this.pointers.set(e.pointerId, { x: e.offsetX, y: e.offsetY });
      if (this.pointers.size === 2) {
        const [a, b] = [...this.pointers.values()];
        this.pinch = { dist: Math.hypot(a.x - b.x, a.y - b.y), scale: this.camera.scale };
      }
    });
    c.addEventListener("pointermove", (e) => {
      const prev = this.pointers.get(e.pointerId);
      if (!prev) return;
      const cur = { x: e.offsetX, y: e.offsetY };
      this.pointers.set(e.pointerId, cur);
      if (this.pointers.size === 1) this.panBy(cur.x - prev.x, cur.y - prev.y);
      else if (this.pointers.size === 2 && this.pinch) {
        const [a, b] = [...this.pointers.values()];
        const dist = Math.hypot(a.x - b.x, a.y - b.y);
        const target = clamp((this.pinch.scale * dist) / this.pinch.dist, MIN_SCALE, MAX_SCALE);
        this.zoomBy(target / this.camera.scale, (a.x + b.x) / 2, (a.y + b.y) / 2);
        this.panBy((cur.x - prev.x) / 2, (cur.y - prev.y) / 2);
      }
    });
    const end = (e: PointerEvent) => {
      this.pointers.delete(e.pointerId);
      if (this.pointers.size < 2) this.pinch = null;
    };
    c.addEventListener("pointerup", end);
    c.addEventListener("pointercancel", end);
    c.addEventListener(
      "wheel",
      (e) => {
        e.preventDefault();
        this.zoomBy(Math.exp(-e.deltaY * (e.deltaMode === 1 ? 0.05 : 0.0015)), e.offsetX, e.offsetY);
      },
      { passive: false },
    );
    c.addEventListener("dblclick", () => this.fit());
    c.addEventListener("keydown", (e) => {
      const step = 40;
      const actions: Record<string, () => void> = {
        ArrowLeft: () => this.panBy(step, 0),
        ArrowRight: () => this.panBy(-step, 0),
        ArrowUp: () => this.panBy(0, step),
        ArrowDown: () => this.panBy(0, -step),
        "+": () => this.zoomBy(1.25),
        "=": () => this.zoomBy(1.25),
        "-": () => this.zoomBy(0.8),
        "0": () => this.fit(),
      };
      const act = actions[e.key];
      if (act && !e.ctrlKey && !e.metaKey && !e.altKey) {
        e.preventDefault();
        act();
      }
    });
  }
}

function clamp(v: number, lo: number, hi: number): number {
  return Math.min(hi, Math.max(lo, v));
}

/** Stroke widths grow a little with zoom but stay readable. */
function lineScale(scale: number): number {
  return clamp(Math.sqrt(scale), 0.6, 3);
}
