import * as THREE from "three";
import { OrbitControls } from "three/examples/jsm/controls/OrbitControls.js";
import { LineSegments2 } from "three/examples/jsm/lines/LineSegments2.js";
import { LineSegmentsGeometry } from "three/examples/jsm/lines/LineSegmentsGeometry.js";
import { LineMaterial } from "three/examples/jsm/lines/LineMaterial.js";
import type { Segment, TurtleState } from "../lang";
import { animated, cssVar, drawingBounds } from "./geometry";

/** True when this browser can create a WebGL context. */
export function webglAvailable(): boolean {
  try {
    const c = document.createElement("canvas");
    return !!(c.getContext("webgl2") || c.getContext("webgl"));
  } catch {
    return false;
  }
}

/** The spatial view: orbit camera, ground grid, axes and the turtle. */
export class View3D {
  readonly canvas: HTMLCanvasElement;
  private renderer: THREE.WebGLRenderer;
  private scene = new THREE.Scene();
  private camera = new THREE.PerspectiveCamera(45, 1, 0.5, 20000);
  private controls: OrbitControls;
  private drawing = new THREE.Group();
  private turtleMesh: THREE.Group;
  private grid: THREE.GridHelper;
  private axes: THREE.Group;
  private materials: LineMaterial[] = [];
  private segments: Segment[] = [];
  private turtle: TurtleState | null = null;
  private glide = 1;
  private frame = 0;
  private lastKey = "";
  userMoved = false;

  constructor(host: HTMLElement) {
    this.renderer = new THREE.WebGLRenderer({ antialias: true, preserveDrawingBuffer: true });
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
    this.canvas = this.renderer.domElement;
    this.canvas.className = "view-canvas";
    this.canvas.tabIndex = 0;
    this.canvas.setAttribute("role", "img");
    this.canvas.setAttribute(
      "aria-label",
      "Rysunek 3D. Przeciągnij, aby obracać kamerę; prawy przycisk lub dwa palce przesuwają; kółko lub szczypanie przybliża. Z klawiatury: strzałki obracają, plus i minus przybliżają, zero dopasowuje.",
    );
    host.append(this.canvas);

    this.camera.up.set(0, 0, 1);
    this.controls = new OrbitControls(this.camera, this.canvas);
    this.controls.enableDamping = true;
    this.controls.dampingFactor = 0.12;
    this.controls.addEventListener("change", () => this.requestDraw());
    this.controls.addEventListener("start", () => (this.userMoved = true));

    this.grid = new THREE.GridHelper(400, 20);
    this.grid.rotation.x = Math.PI / 2; // into the XY plane (z = 0)
    this.scene.add(this.grid);
    this.axes = makeAxes(120);
    this.scene.add(this.axes);
    this.scene.add(this.drawing);
    this.turtleMesh = makeTurtle();
    this.scene.add(this.turtleMesh);
    this.scene.add(new THREE.HemisphereLight(0xffffff, 0x667766, 2.2));
    const sun = new THREE.DirectionalLight(0xffffff, 1.2);
    sun.position.set(200, -300, 500);
    this.scene.add(sun);

    this.resetCamera();
    this.applyTheme();
    new ResizeObserver(() => this.resize()).observe(host);
    this.canvas.addEventListener("keydown", (e) => this.onKey(e));
    this.resize();
  }

  setDrawing(segments: Segment[], turtle: TurtleState | null, glide = 1): void {
    this.segments = segments;
    this.turtle = turtle;
    this.glide = glide;
    this.rebuild();
    this.requestDraw();
  }

  resetCamera(): void {
    this.camera.position.set(220, -320, 260);
    this.controls.target.set(0, 0, 0);
    this.controls.update();
    this.userMoved = false;
    this.requestDraw();
  }

  /** Frames the whole drawing from the current viewing direction. */
  fit(): void {
    const b = drawingBounds(this.segments, this.turtle ?? undefined);
    const center = new THREE.Vector3((b.min[0] + b.max[0]) / 2, (b.min[1] + b.max[1]) / 2, (b.min[2] + b.max[2]) / 2);
    const size = new THREE.Vector3(b.max[0] - b.min[0], b.max[1] - b.min[1], b.max[2] - b.min[2]);
    const radius = Math.max(size.length() / 2, 20);
    const dir = this.camera.position.clone().sub(this.controls.target).normalize();
    if (dir.lengthSq() === 0) dir.set(0.45, -0.65, 0.6).normalize();
    const fov = (this.camera.fov * Math.PI) / 180;
    const fovMin = Math.min(fov, 2 * Math.atan(Math.tan(fov / 2) * this.camera.aspect));
    const dist = (radius / Math.sin(fovMin / 2)) * 1.08;
    this.controls.target.copy(center);
    this.camera.position.copy(center).add(dir.multiplyScalar(dist));
    this.camera.far = Math.max(20000, dist * 10);
    this.camera.updateProjectionMatrix();
    this.controls.update();
    this.userMoved = false;
    this.requestDraw();
  }

  zoomBy(factor: number): void {
    const offset = this.camera.position.clone().sub(this.controls.target).divideScalar(factor);
    this.camera.position.copy(this.controls.target).add(offset);
    this.controls.update();
    this.userMoved = true;
    this.requestDraw();
  }

  isOutOfView(): boolean {
    if (!this.turtle) return false;
    const p = new THREE.Vector3(...this.turtle.position).project(this.camera);
    return Math.abs(p.x) > 0.95 || Math.abs(p.y) > 0.95 || p.z > 1;
  }

  applyTheme(): void {
    this.scene.background = new THREE.Color(cssVar("--paper", "#fbf8f1"));
    const grid = this.grid.material as THREE.LineBasicMaterial;
    grid.color = new THREE.Color(cssVar("--grid", "#e7e1d3"));
    grid.vertexColors = false;
    this.requestDraw();
  }

  toPNG(): string {
    this.draw();
    return this.canvas.toDataURL("image/png");
  }

  private onKey(e: KeyboardEvent): void {
    if (e.ctrlKey || e.metaKey || e.altKey) return;
    const rotate = (az: number, pol: number) => {
      const offset = this.camera.position.clone().sub(this.controls.target);
      const sph = new THREE.Spherical().setFromVector3(new THREE.Vector3(offset.x, offset.z, -offset.y));
      sph.theta += az;
      sph.phi = Math.min(Math.PI - 0.05, Math.max(0.05, sph.phi + pol));
      const v = new THREE.Vector3().setFromSpherical(sph);
      this.camera.position.copy(this.controls.target).add(new THREE.Vector3(v.x, -v.z, v.y));
      this.controls.update();
      this.userMoved = true;
      this.requestDraw();
    };
    const actions: Record<string, () => void> = {
      ArrowLeft: () => rotate(-0.15, 0),
      ArrowRight: () => rotate(0.15, 0),
      ArrowUp: () => rotate(0, -0.12),
      ArrowDown: () => rotate(0, 0.12),
      "+": () => this.zoomBy(1.25),
      "=": () => this.zoomBy(1.25),
      "-": () => this.zoomBy(0.8),
      "0": () => this.fit(),
    };
    const act = actions[e.key];
    if (act) {
      e.preventDefault();
      act();
    }
  }

  private rebuild(): void {
    const view = this.turtle ? animated(this.segments, this.turtle, this.glide) : { segments: this.segments, turtle: null };
    const last = view.segments[view.segments.length - 1];
    const key = `${view.segments.length}:${last ? last.to.join(",") : ""}`;
    if (key !== this.lastKey) {
      this.lastKey = key;
      for (const child of [...this.drawing.children]) {
        (child as LineSegments2).geometry.dispose();
        this.drawing.remove(child);
      }
      this.materials.forEach((m) => m.dispose());
      this.materials = [];
      const byWidth = new Map<number, Segment[]>();
      for (const s of view.segments) {
        const list = byWidth.get(s.width) ?? [];
        list.push(s);
        byWidth.set(s.width, list);
      }
      const size = this.renderer.getSize(new THREE.Vector2());
      for (const [width, segs] of byWidth) {
        const positions = new Float32Array(segs.length * 6);
        const colors = new Float32Array(segs.length * 6);
        const c = new THREE.Color();
        segs.forEach((s, i) => {
          positions.set([...s.from, ...s.to], i * 6);
          c.set(s.color);
          // three.js treats sRGB hex as linear for vertex colours; convert for correct tone
          c.convertSRGBToLinear();
          colors.set([c.r, c.g, c.b, c.r, c.g, c.b], i * 6);
        });
        const geometry = new LineSegmentsGeometry();
        geometry.setPositions(positions);
        geometry.setColors(colors);
        const material = new LineMaterial({ linewidth: width * 1.2, vertexColors: true, worldUnits: false });
        material.resolution.set(size.x, size.y);
        this.materials.push(material);
        this.drawing.add(new LineSegments2(geometry, material));
      }
    }
    const t = view.turtle;
    this.turtleMesh.visible = !!t;
    if (t) {
      const m = new THREE.Matrix4().makeBasis(
        new THREE.Vector3(...t.right),
        new THREE.Vector3(...t.heading),
        new THREE.Vector3(...t.up),
      );
      this.turtleMesh.quaternion.setFromRotationMatrix(m);
      this.turtleMesh.position.set(...t.position);
      const body = this.turtleMesh.children[0] as THREE.Mesh;
      (body.material as THREE.MeshStandardMaterial).color.set(t.penDown ? t.color : "#ffffff");
    }
  }

  private resize(): void {
    const host = this.canvas.parentElement!;
    const rect = host.getBoundingClientRect();
    const w = Math.max(1, rect.width), hgt = Math.max(1, rect.height);
    this.renderer.setSize(w, hgt, false);
    this.canvas.style.width = `${w}px`;
    this.canvas.style.height = `${hgt}px`;
    this.camera.aspect = w / hgt;
    this.camera.updateProjectionMatrix();
    const size = this.renderer.getSize(new THREE.Vector2());
    this.materials.forEach((m) => m.resolution.set(size.x, size.y));
    this.draw();
  }

  private requestDraw(): void {
    if (this.frame) return;
    this.frame = requestAnimationFrame(() => {
      this.frame = 0;
      this.draw();
      if (this.controls.update()) this.requestDraw();
    });
  }

  draw(): void {
    // keep the turtle a readable size whatever the zoom
    const dist = this.camera.position.distanceTo(this.controls.target);
    this.turtleMesh.scale.setScalar(Math.max(0.4, dist / 300));
    this.renderer.render(this.scene, this.camera);
  }
}

function makeAxes(length: number): THREE.Group {
  const g = new THREE.Group();
  const defs: [THREE.Vector3, string, string][] = [
    [new THREE.Vector3(1, 0, 0), "#d0473c", "x"],
    [new THREE.Vector3(0, 1, 0), "#3c9b4a", "y"],
    [new THREE.Vector3(0, 0, 1), "#3a6fd0", "z"],
  ];
  for (const [dir, color, label] of defs) {
    const geo = new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(), dir.clone().multiplyScalar(length)]);
    g.add(new THREE.Line(geo, new THREE.LineBasicMaterial({ color })));
    const sprite = makeLabel(label, color);
    sprite.position.copy(dir.clone().multiplyScalar(length + 12));
    g.add(sprite);
  }
  const origin = new THREE.Mesh(new THREE.SphereGeometry(2.2, 16, 12), new THREE.MeshBasicMaterial({ color: "#8d8170" }));
  g.add(origin);
  return g;
}

function makeLabel(text: string, color: string): THREE.Sprite {
  const c = document.createElement("canvas");
  c.width = c.height = 64;
  const ctx = c.getContext("2d")!;
  ctx.font = "bold 44px system-ui, sans-serif";
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  ctx.fillStyle = color;
  ctx.fillText(text, 32, 34);
  const sprite = new THREE.Sprite(new THREE.SpriteMaterial({ map: new THREE.CanvasTexture(c), depthTest: false }));
  sprite.scale.set(14, 14, 1);
  return sprite;
}

/** A dart: the cone points along the heading, the fin along the turtle's up. */
function makeTurtle(): THREE.Group {
  const g = new THREE.Group();
  const body = new THREE.Mesh(
    new THREE.ConeGeometry(5, 16, 4),
    new THREE.MeshStandardMaterial({ color: "#16866a", roughness: 0.5, flatShading: true }),
  );
  body.rotation.y = Math.PI / 4; // flat faces left/right
  body.scale.set(1, 1, 0.55);
  const fin = new THREE.Mesh(
    new THREE.BoxGeometry(1.2, 7, 6),
    new THREE.MeshStandardMaterial({ color: "#1f2a27", roughness: 0.6 }),
  );
  fin.position.set(0, -2, 3.5);
  g.add(body, fin);
  return g;
}
