import type { Mode, Segment, Vec3 } from "../lang";
import { cssVar } from "./geometry";

/** Isometric-ish projection for 3D thumbnails (z up). */
function project(p: Vec3, mode: Mode): [number, number] {
  if (mode === "2d") return [p[0], p[1]];
  const a = Math.PI / 6;
  const x = (p[0] - p[1]) * Math.cos(a);
  const y = (p[0] + p[1]) * Math.sin(a) * 0.9 + p[2];
  return [x, y];
}

export interface PreviewLayer {
  segments: Segment[];
  /** Overrides segment colours (e.g. a faint target). */
  color?: string;
  alpha?: number;
  widthScale?: number;
}

/** Draws one or more drawings into a canvas, fitted, with the origin marked. */
export function drawPreview(canvas: HTMLCanvasElement, mode: Mode, layers: PreviewLayer[], size?: { w: number; h: number }): void {
  const w = size?.w ?? (canvas.clientWidth || 240);
  const hgt = size?.h ?? (canvas.clientHeight || 160);
  const dpr = window.devicePixelRatio || 1;
  canvas.width = Math.round(w * dpr);
  canvas.height = Math.round(hgt * dpr);
  const ctx = canvas.getContext("2d");
  if (!ctx) return;
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  ctx.fillStyle = cssVar("--paper", "#fbf8f1");
  ctx.fillRect(0, 0, w, hgt);

  let minX = 0, minY = 0, maxX = 0, maxY = 0;
  for (const l of layers)
    for (const s of l.segments)
      for (const p of [s.from, s.to]) {
        const [x, y] = project(p, mode);
        minX = Math.min(minX, x);
        maxX = Math.max(maxX, x);
        minY = Math.min(minY, y);
        maxY = Math.max(maxY, y);
      }
  const pad = 14;
  const scale = Math.min((w - pad * 2) / Math.max(maxX - minX, 1), (hgt - pad * 2) / Math.max(maxY - minY, 1), 4);
  const cx = (minX + maxX) / 2, cy = (minY + maxY) / 2;
  const toScreen = (p: Vec3): [number, number] => {
    const [x, y] = project(p, mode);
    return [(x - cx) * scale + w / 2, -(y - cy) * scale + hgt / 2];
  };

  if (mode === "3d") {
    // a hint of the ground axes
    ctx.strokeStyle = cssVar("--grid", "#e7e1d3");
    ctx.lineWidth = 1;
    const o = toScreen([0, 0, 0]);
    for (const d of [[60, 0, 0], [0, 60, 0], [0, 0, 60]] as Vec3[]) {
      const e = toScreen(d.map((v) => v / Math.max(scale, 0.3)) as Vec3);
      ctx.beginPath();
      ctx.moveTo(o[0], o[1]);
      ctx.lineTo(e[0], e[1]);
      ctx.stroke();
    }
  }

  ctx.lineCap = "round";
  ctx.lineJoin = "round";
  for (const l of layers) {
    ctx.globalAlpha = l.alpha ?? 1;
    for (const s of l.segments) {
      const a = toScreen(s.from), b = toScreen(s.to);
      ctx.strokeStyle = l.color ?? s.color;
      ctx.lineWidth = Math.max(1, Math.min(s.width, 4) * (l.widthScale ?? 0.8));
      ctx.beginPath();
      ctx.moveTo(a[0], a[1]);
      ctx.lineTo(b[0], b[1]);
      ctx.stroke();
    }
  }
  ctx.globalAlpha = 1;
  const o = toScreen([0, 0, 0]);
  ctx.fillStyle = cssVar("--axis-strong", "#8d8170");
  ctx.beginPath();
  ctx.arc(o[0], o[1], 3, 0, Math.PI * 2);
  ctx.fill();
}
