export type ThemeChoice = "auto" | "light" | "dark";
const KEY = "logomocja.v1.theme";
const listeners = new Set<() => void>();
const media = window.matchMedia("(prefers-color-scheme: dark)");

export function themeChoice(): ThemeChoice {
  try {
    const v = localStorage.getItem(KEY);
    return v === "light" || v === "dark" ? v : "auto";
  } catch {
    return "auto";
  }
}

export function effectiveTheme(choice = themeChoice()): "light" | "dark" {
  return choice === "auto" ? (media.matches ? "dark" : "light") : choice;
}

export function applyTheme(): void {
  const theme = effectiveTheme();
  document.documentElement.dataset.theme = theme;
  document.querySelector('meta[name="theme-color"]')?.setAttribute("content", theme === "dark" ? "#17201e" : "#f4efe4");
  listeners.forEach((l) => l());
}

export function setThemeChoice(choice: ThemeChoice): void {
  try {
    if (choice === "auto") localStorage.removeItem(KEY);
    else localStorage.setItem(KEY, choice);
  } catch {
    /* ignore */
  }
  applyTheme();
}

export function onThemeChange(fn: () => void): void {
  listeners.add(fn);
}

media.addEventListener("change", () => {
  if (themeChoice() === "auto") applyTheme();
});
EOF
