import type { Mode } from "../lang";
import type { Studio, StudioState } from "../app/studio";
import { MAX_SPEED, MIN_SPEED } from "../app/studio";
import { h, icon, ICONS } from "./dom";
import { Editor } from "./editor";
import { onThemeChange } from "./theme";
import { toast } from "./toast";
import { View2D } from "./view2d";
import type { View3D } from "./view3d";

const STATUS_LABEL: Record<StudioState["status"], string> = {
  idle: "Gotowy do uruchomienia",
  running: "Rysuję…",
  paused: "Wstrzymano",
  done: "Gotowe",
  error: "Błąd",
  stopped: "Zatrzymano",
};

export const SHORTCUTS: [keys: string, action: string][] = [
  ["Ctrl + Enter (⌘ + Enter) lub Alt + U", "Uruchom program"],
  ["Alt + K", "Wykonaj jeden krok"],
  ["Alt + P", "Pauza / wznów"],
  ["Alt + R", "Resetuj rysunek"],
  ["Alt + 2 / Alt + 3", "Tryb 2D / tryb 3D"],
  ["Tab / Shift + Tab", "Przejdź do następnej / poprzedniej kontrolki (także z edytora)"],
  ["Strzałki, + / −, 0 (na rysunku)", "Przesuń lub obróć widok, przybliż / oddal, dopasuj"],
];

export interface StudioPage {
  root: HTMLElement;
  editor: Editor;
  /** Fits the active view and waits until the drawing is painted. */
  fitAndPaint(): Promise<void>;
  /** Resolves once the view for the current mode is ready (3D loads lazily). */
  ready(): Promise<void>;
  onShown(): void;
}

export function createStudioPage(studio: Studio): StudioPage {
  const editor = new Editor({
    id: "program-editor",
    label: "Program w języku Logo",
    onChange: (v) => studio.setSource(v),
  });

  // --- controls -------------------------------------------------------------
  const modeButtons = (["2d", "3d"] as Mode[]).map((m) =>
    h(
      "button",
      {
        type: "button",
        class: "seg-btn",
        "data-mode": m,
        "aria-pressed": "false",
        "aria-keyshortcuts": m === "2d" ? "Alt+2" : "Alt+3",
        onclick: () => switchMode(m),
      },
      m.toUpperCase(),
    ),
  );
  const modeGroup = h("div", { class: "segmented", role: "group", "aria-label": "Tryb rysowania" }, ...modeButtons);

  const btn = (label: string, iconPaths: string, onclick: () => void, extra: Record<string, string> = {}) =>
    h("button", { type: "button", class: "btn", onclick, title: label, ...extra }, icon(iconPaths), h("span", { class: "btn-label" }, label));

  const runBtn = btn("Uruchom", ICONS.play, () => studio.run(), { class: "btn btn-primary", "aria-keyshortcuts": "Control+Enter Alt+U" });
  const stepBtn = btn("Krok", ICONS.step, () => studio.step(), { "aria-keyshortcuts": "Alt+K" });
  const pauseBtn = btn("Pauza", ICONS.pause, () => togglePause(), { "aria-keyshortcuts": "Alt+P" });
  const resetBtn = btn("Reset", ICONS.reset, () => studio.reset(), { "aria-keyshortcuts": "Alt+R" });

  const speedId = "speed-control";
  const speed = h("input", {
    id: speedId,
    type: "range",
    min: MIN_SPEED,
    max: MAX_SPEED,
    step: 1,
    value: studio.state.speed,
    "aria-valuetext": speedText(studio.state.speed),
    oninput: () => studio.setSpeed(Number(speed.value)),
  });
  const speedBox = h("div", { class: "speed" }, h("label", { for: speedId }, "Szybkość"), speed);

  const toolbar = h(
    "div",
    { class: "toolbar", role: "toolbar", "aria-label": "Sterowanie programem" },
    modeGroup,
    h("div", { class: "toolbar-group" }, runBtn, stepBtn, pauseBtn, resetBtn),
    speedBox,
  );

  // --- file actions -----------------------------------------------------------
  const fileInput = h("input", { type: "file", accept: ".logo,.txt,text/plain", class: "visually-hidden", tabindex: "-1", "aria-hidden": "true" });
  fileInput.addEventListener("change", async () => {
    const file = fileInput.files?.[0];
    fileInput.value = "";
    if (!file) return;
    if (file.size > 200_000) return toast("Ten plik jest za duży jak na program Logo.");
    const text = await file.text();
    const hadStash = studio.state.stash;
    studio.openFile(file.name, text);
    toast(`Otwarto plik ${file.name}.`);
    noteStash(hadStash);
  });
  const smallBtn = (label: string, iconPaths: string, onclick: () => void) =>
    h("button", { type: "button", class: "btn btn-small", onclick }, icon(iconPaths), h("span", {}, label));
  const fileActions = h(
    "div",
    { class: "panel-actions" },
    smallBtn("Otwórz plik", ICONS.upload, () => fileInput.click()),
    smallBtn("Zapisz .logo", ICONS.download, () => {
      const f = studio.programFile();
      download(f.name, URL.createObjectURL(new Blob([f.content], { type: f.type })), true);
    }),
    smallBtn("Udostępnij", ICONS.link, () => void share()),
    fileInput,
  );

  const statusText = h("span", { class: "status-text" });
  const statusDot = h("span", { class: "status-dot", "aria-hidden": "true" });
  const errorBox = h("div", { class: "error-box", hidden: true });
  const status = h("div", { class: "status", role: "status", "aria-live": "polite" }, statusDot, statusText);
  const stashBar = h("div", { class: "stash-bar", hidden: true });

  const editorPanel = h(
    "section",
    { class: "panel editor-panel", "aria-labelledby": "editor-title" },
    h("div", { class: "panel-head" }, h("h2", { id: "editor-title", class: "panel-title" }, h("label", { for: "program-editor" }, "Program")), fileActions),
    stashBar,
    editor.root,
    h("div", { class: "panel-foot" }, status, errorBox),
  );

