function speedText(v: number): string {
  if (v >= MAX_SPEED) return `${v} z ${MAX_SPEED}: natychmiast`;
  if (v <= 2) return `${v} z ${MAX_SPEED}: bardzo wolno`;
  if (v <= 4) return `${v} z ${MAX_SPEED}: wolno`;
  if (v <= 7) return `${v} z ${MAX_SPEED}: średnio`;
  return `${v} z ${MAX_SPEED}: szybko`;
}

function plural(n: number, one: string, few: string, many: string): string {
  if (n === 1) return one;
  const d = n % 10, dd = n % 100;
  return d >= 2 && d <= 4 && (dd < 12 || dd > 14) ? few : many;
}

function download(name: string, href: string, revoke: boolean) {
  const a = h("a", { href, download: name });
  document.body.append(a);
  a.click();
  a.remove();
  if (revoke) setTimeout(() => URL.revokeObjectURL(href), 2000);
}
