import type { ChallengeBook, Challenge, CheckResult } from "../app/challenges";
import { h, icon, ICONS } from "./dom";
import { Editor } from "./editor";
import { drawPreview } from "./preview";
import { onThemeChange } from "./theme";

export function createChallengesPage(book: ChallengeBook, navigate: (hash: string) => void) {
  const list = h("ol", { class: "challenge-list", role: "list" });
  const counter = h("p", { class: "lead" });
  const detail = h("div", { class: "challenge-detail" });
  const root = h(
    "div",
    { class: "page challenges-page" },
    h("div", { class: "page-head" }, h("h1", {}, "Wyzwania"), counter),
    h("div", { class: "challenges-layout" }, h("nav", { "aria-label": "Lista wyzwań" }, list), detail),
  );
  let current: Challenge | null = null;
  let lastResult: CheckResult | null = null;
  let preview: HTMLCanvasElement | null = null;

  function renderList() {
    const progress = book.progress();
    const done = book.list.filter((c) => progress[c.id]?.passed).length;
    counter.textContent = `Narysuj wzór własnym programem. Program sprawdza sam rysunek: kształt i położenie (z tolerancją 1,5 jednostki), bez kolorów i grubości. Zaliczone: ${done} z ${book.list.length}.`;
    list.replaceChildren(
      ...book.list.map((c, i) => {
        const passed = !!progress[c.id]?.passed;
        return h(
          "li",
          {},
          h(
            "a",
            {
              href: `#/wyzwania/${c.id}`,
              class: `challenge-link${current?.id === c.id ? " is-current" : ""}`,
              "aria-current": current?.id === c.id ? "page" : null,
            },
            h("span", { class: "challenge-num" }, String(i + 1)),
            h("span", { class: "challenge-name" }, c.title),
            h("span", { class: `badge badge-${c.mode}` }, c.mode.toUpperCase()),
            passed ? h("span", { class: "passed-mark", title: "Zaliczone" }, icon(ICONS.check), h("span", { class: "visually-hidden" }, " (zaliczone)")) : null,
          ),
        );
      }),
    );
  }

  function paintPreview() {
    if (!current || !preview) return;
    const layers = [{ segments: current.target, color: "var(--target)", alpha: 1, widthScale: 1.6 }];
    // canvas can't read CSS vars in strokeStyle; resolve them
    const target = getComputedStyle(document.documentElement).getPropertyValue("--target").trim() || "#c9bfa9";
    layers[0].color = target;
    const all = lastResult && lastResult.segments.length ? [...layers, { segments: lastResult.segments, color: undefined as unknown as string, alpha: 0.95, widthScale: 0.8 }] : layers;
    drawPreview(preview, current.mode, all, { w: preview.parentElement!.clientWidth || 320, h: 260 });
  }

  function show(id: string | null) {
    current = (id && book.list.find((c) => c.id === id)) || null;
    lastResult = null;
    renderList();
    if (!current) {
      preview = null;
      detail.replaceChildren(h("div", { class: "empty" }, h("p", {}, "Wybierz wyzwanie z listy."), h("a", { class: "btn btn-primary", href: `#/wyzwania/${book.list[0].id}` }, "Zacznij od pierwszego")));
      return;
    }
    const c = current;
    const editor = new Editor({ id: "challenge-editor", label: `Twój program dla wyzwania ${c.title}`, onChange: (v) => book.saveAttempt(c.id, v) });
    editor.setValue(book.attempt(c.id) ?? "");
    preview = h("canvas", { class: "challenge-canvas", role: "img", "aria-label": `Wzór do narysowania: ${c.task}` });
    const result = h("div", { class: "check-result", role: "status", "aria-live": "polite" });
    const solution = h("details", { class: "solution", hidden: !book.progress()[c.id]?.passed }, h("summary", {}, "Przykładowe rozwiązanie"), h("pre", { class: "code-block" }, c.solution));
    const check = () => {
      const r = book.check(c.id, editor.value);
      lastResult = r;
      result.className = `check-result ${r.passed ? "is-pass" : "is-fail"}`;
      result.replaceChildren(h("strong", {}, r.passed ? "Zaliczone! " : "Jeszcze nie. "), r.reason);
      if (r.passed) solution.hidden = false;
      renderList();
      paintPreview();
    };
    const idx = book.list.indexOf(c);
    const next = book.list[idx + 1];
    detail.replaceChildren(
      h("h2", {}, `${idx + 1}. ${c.title} `, h("span", { class: `badge badge-${c.mode}` }, c.mode === "2d" ? "tryb 2D" : "tryb 3D")),
      h("p", { class: "task" }, c.task),
      h("div", { class: "challenge-grid" },
        h("figure", { class: "challenge-figure" }, preview, h("figcaption", {}, "Szary wzór to cel. Po sprawdzeniu na wierzch nakłada się Twój rysunek.")),
        h("div", { class: "challenge-work" },
          h("label", { for: "challenge-editor", class: "field-label" }, "Twój program"),
          editor.root,
          h("div", { class: "row" },
            h("button", { type: "button", class: "btn btn-primary", onclick: check }, icon(ICONS.check), h("span", {}, "Sprawdź")),
            h("details", { class: "hint" }, h("summary", {}, "Podpowiedź"), h("p", {}, c.hint)),
          ),
          result,
          solution,
          next ? h("p", {}, h("a", { href: `#/wyzwania/${next.id}`, onclick: () => navigate(`#/wyzwania/${next.id}`) }, `Następne: ${next.title} →`)) : null,
        ),
      ),
    );
    requestAnimationFrame(paintPreview);
  }

  onThemeChange(paintPreview);
  window.addEventListener("resize", () => paintPreview());
  return { root, show };
}
