cd /work && sed -i 's/h("h2", { id: `ref-${id}-h` }, title)/h("h2", { id: `ref-${id}-h`, tabindex: "-1" }, title)/' src/ui/referencePage.ts && cat > src/main.ts <<'EOF'
import "./styles.css";
import { run, type Mode, type RunResult } from "./lang";
import { createStudio } from "./app/studio";
import { createChallengeBook } from "./app/challenges";
import { decodeShare } from "./app/share";
import { h, icon, ICONS } from "./ui/dom";
import { createStudioPage, SHORTCUTS } from "./ui/studioPage";
import { createExamplesPage } from "./ui/examplesPage";
import { createChallengesPage } from "./ui/challengesPage";
import { createReferencePage } from "./ui/referencePage";
import { applyTheme, setThemeChoice, themeChoice, type ThemeChoice } from "./ui/theme";
import { toast } from "./ui/toast";

declare const __APP_VERSION__: string;

function browserStorage(): Storage | { getItem(): null; setItem(): void; removeItem(): void } {
  try {
    const s = window.localStorage;
    s.getItem("x");
    return s;
  } catch {
    return { getItem: () => null, setItem: () => {}, removeItem: () => {} };
  }
}

applyTheme();
const storage = browserStorage();
const studio = createStudio({
  storage,
  scheduler: { request: (cb) => requestAnimationFrame(cb), cancel: (id) => cancelAnimationFrame(id) },
});
const book = createChallengeBook(storage);

// --- pages -----------------------------------------------------------------------
const studioPage = createStudioPage(studio);
const goStudio = () => navigate("#/");
const withStashNote = (fn: () => void) => {
  const before = studio.state.stash;
  fn();
  if (studio.state.stash !== null && studio.state.stash !== before) {
    toast("Twój poprzedni szkic jest bezpieczny.", { label: "Przywróć szkic", run: () => studio.restoreStash() });
  }
};
const examplesPage = createExamplesPage((name) => {
  withStashNote(() => studio.loadExample(name));
  goStudio();
  void studioPage.ready().then(() => studio.run());
});
const challengesPage = createChallengesPage(book, (hash) => navigate(hash));
const referencePage = createReferencePage((source, mode) => {
  withStashNote(() => studio.replaceDraft(source, mode));
  goStudio();
  void studioPage.ready().then(() => studio.run());
});

type Route = "studio" | "przyklady" | "wyzwania" | "pomoc";
const pages: Record<Route, HTMLElement> = {
  studio: studioPage.root,
  przyklady: examplesPage.root,
  wyzwania: challengesPage.root,
  pomoc: referencePage,
};
const titles: Record<Route, string> = { studio: "Studio", przyklady: "Przykłady", wyzwania: "Wyzwania", pomoc: "Pomoc" };

// --- shell ---------------------------------------------------------------------------
const navLinks = (Object.keys(titles) as Route[]).map((r) =>
  h("a", { href: r === "studio" ? "#/" : `#/${r}`, class: "nav-link", "data-route": r }, titles[r]),
);

const themeLabels: Record<ThemeChoice, string> = { auto: "Motyw: jak w systemie", light: "Motyw: jasny", dark: "Motyw: ciemny" };
const themeIcons: Record<ThemeChoice, string> = { auto: ICONS.auto, light: ICONS.sun, dark: ICONS.moon };
const themeBtn = h("button", { type: "button", class: "btn btn-icon" });
const renderThemeBtn = () => {
  const c = themeChoice();
  themeBtn.replaceChildren(icon(themeIcons[c]));
  themeBtn.setAttribute("aria-label", `${themeLabels[c]}. Kliknij, aby zmienić.`);
  themeBtn.title = themeLabels[c];
};
themeBtn.addEventListener("click", () => {
  const order: ThemeChoice[] = ["auto", "light", "dark"];
  setThemeChoice(order[(order.indexOf(themeChoice()) + 1) % 3]);
  renderThemeBtn();
  toast(themeLabels[themeChoice()]);
});
renderThemeBtn();

const shortcutsDialog = h(
  "dialog",
  { class: "dialog", "aria-labelledby": "shortcuts-title" },
  h("h2", { id: "shortcuts-title" }, "Skróty klawiszowe"),
  h("table", { class: "shortcut-table" }, h("tbody", {}, ...SHORTCUTS.map(([k, a]) => h("tr", {}, h("td", {}, h("kbd", {}, k)), h("td", {}, a))))),
  h("form", { method: "dialog" }, h("button", { class: "btn btn-primary", type: "submit" }, "Zamknij")),
);
const shortcutsBtn = h(
  "button",
  { type: "button", class: "btn btn-icon", "aria-label": "Skróty klawiszowe", title: "Skróty klawiszowe", "aria-haspopup": "dialog", onclick: () => shortcutsDialog.showModal() },
  icon(ICONS.keyboard),
);

const logo = `<svg viewBox="0 0 40 40" aria-hidden="true" class="logo-mark"><path d="M20 4 L31 30 L20 24 L9 30 Z" fill="currentColor"/><circle cx="20" cy="33" r="2.4" fill="var(--accent-2)"/></svg>`;
const brand = h("a", { href: "#/", class: "brand", "aria-label": "Logomocja: studio" });
brand.innerHTML = `${logo}<span>Logomocja</span>`;

const main = h("main", { id: "main", tabindex: "-1" }, ...Object.values(pages));
document.getElementById("app")!.replaceChildren(
  h("a", { href: "#main", class: "skip-link", onclick: (e: Event) => { e.preventDefault(); main.focus(); } }, "Przejdź do treści"),
  h("header", { class: "site-header" }, brand, h("nav", { class: "site-nav", "aria-label": "Główna nawigacja" }, ...navLinks), h("div", { class: "header-tools" }, shortcutsBtn, themeBtn)),
  main,
  shortcutsDialog,
  h("div", { id: "toasts", class: "toasts", "aria-live": "polite" }),
);

// --- routing (hash based, so any refresh works on a static host) -------------------
function navigate(hash: string) {
  if (location.hash === hash || (hash === "#/" && (location.hash === "" || location.hash === "#"))) route();
  else location.hash = hash;
}

let currentRoute: Route | null = null;
function route() {
  const hash = location.hash || "#/";
  if (decodeShare(hash)) {
    withStashNote(() => studio.openPermalink(location.href));
    history.replaceState(null, "", location.pathname + location.search + "#/");
    void studioPage.ready().then(() => {
      if (studio.state.status !== "running" && studio.state.status !== "done") studio.run();
    });
    return show("studio");
  }
  const [, first, second] = hash.replace(/^#/, "").split(/[/?]/);
  const r: Route = first === "przyklady" || first === "wyzwania" || first === "pomoc" ? first : "studio";
  show(r);
  if (r === "wyzwania") challengesPage.show(second || null);
}

function show(r: Route) {
  for (const [name, el] of Object.entries(pages)) el.hidden = name !== r;
  navLinks.forEach((a) => (a.dataset.route === r ? a.setAttribute("aria-current", "page") : a.removeAttribute("aria-current")));
  document.title = r === "studio" ? "Logomocja — studio żółwia" : `${titles[r]} — Logomocja`;
  if (r === "studio") studioPage.onShown();
  if (r === "przyklady") examplesPage.onShown();
  if (currentRoute !== null && currentRoute !== r) main.focus({ preventScroll: true });
  if (currentRoute !== r) window.scrollTo(0, 0);
  currentRoute = r;
}

window.addEventListener("hashchange", route);
route();

// --- testing hook --------------------------------------------------------------------------
declare global {
  interface Window {
    logomocja: {
      version: string;
      run(source: string, mode: Mode): RunResult;
      open(source: string, mode: Mode): Promise<RunResult>;
    };
  }
}

window.logomocja = {
  version: __APP_VERSION__,
  run: (source, mode) => run(String(source), mode === "3d" ? "3d" : "2d"),
  async open(source, mode) {
    const m: Mode = mode === "3d" ? "3d" : "2d";
    if (currentRoute !== "studio") {
      history.replaceState(null, "", location.pathname + location.search + "#/");
      show("studio");
    }
    await studioPage.ready();
    const result = studio.open(String(source), m);
    await studioPage.fitAndPaint();
    return result;
  },
};
