  height: var(--code-line);
  padding: 0 0.7em 0 0.5em;
}
.gutter-line.is-exec {
  background: var(--exec);
  color: var(--ink);
  font-weight: 700;
}
.gutter-line.is-error {
  color: #fff;
  background: var(--danger);
  font-weight: 700;
}
:root[data-theme="dark"] .gutter-line.is-error {
  color: #1a0e0d;
}
.editor-code {
  position: relative;
  flex: 1;
  min-width: 0;
  overflow: hidden;
}
.editor-layer,
.editor-input {
  margin: 0;
  padding: 10px 14px;
  font: inherit;
  line-height: inherit;
  tab-size: 2;
  white-space: pre;
  letter-spacing: 0;
  word-spacing: 0;
}
.editor-layer {
  position: absolute;
  inset: 0 auto auto 0;
  min-width: 100%;
  pointer-events: none;
  color: var(--ink);
  will-change: transform;
}
.editor-layer .line {
  height: var(--code-line);
  min-width: max-content;
  padding-right: 14px;
  margin: 0 -14px;
  padding-left: 14px;
}
.editor-layer .line.is-exec {
  background: var(--exec);
}
.editor-layer .line.is-error {
  background: var(--danger-soft);
}
.editor-input {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  resize: none;
  border: 0;
  outline: none;
  background: transparent;
  color: transparent;
  caret-color: var(--ink);
  overflow: auto;
}
.editor-input::selection {
  background: rgba(43, 111, 179, 0.28);
  color: transparent;
}
.editor:focus-within {
  box-shadow: inset 0 0 0 2px var(--focus);
}
.tok-command { color: var(--tok-command); font-weight: 650; }
.tok-keyword { color: var(--tok-keyword); font-weight: 650; }
.tok-number { color: var(--tok-number); }
.tok-name { color: var(--tok-name); }
.tok-proc { color: var(--tok-proc); font-weight: 650; }
.tok-string { color: var(--tok-string); }
.tok-comment { color: var(--tok-comment); font-style: italic; }
.tok-bracket { color: var(--tok-bracket); font-weight: 700; }
.tok-operator { color: var(--tok-operator); }
.has-swatch {
  /* the swatch sits under the opening quote so text width is unchanged */
  background: linear-gradient(var(--swatch), var(--swatch)) left bottom / 0.6ch 3px no-repeat;
}
.tok-error {
  text-decoration: wavy underline var(--danger);
  text-decoration-thickness: 2px;
  text-underline-offset: 3px;
  background: color-mix(in srgb, var(--danger) 18%, transparent);
  border-radius: 2px;
}
.tok-eol {
  display: inline-block;
  width: 1ch;
}
.inline-error {
  margin-left: 2.5ch;
  padding: 0 0.6em;
  border-radius: 4px;
  background: var(--danger);
  color: #fff;
  font-family: var(--font-ui);
  font-size: 0.85em;
  font-weight: 560;
  white-space: nowrap;
}
:root[data-theme="dark"] .inline-error {
  color: #1a0e0d;
}

/* --- view ------------------------------------------------------------------------------ */
.view-stage {
  position: relative;
  flex: 1;
  min-height: 0;
  background: var(--paper);
}
.view-host {
  position: absolute;
  inset: 0;
}
.view-canvas {
  display: block;
  width: 100%;
  height: 100%;
  touch-action: none;
  cursor: grab;
}
.view-canvas:active {
  cursor: grabbing;
}
.view-canvas:focus-visible {
  outline-offset: -3px;
}
.view-note {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  padding: 24px;
  text-align: center;
  color: var(--ink-soft);
  font-size: 1.02rem;
  max-width: 60ch;
  margin: auto;
}

/* --- toasts & dialog ------------------------------------------------------------------------ */
.toasts {
  position: fixed;
  right: 16px;
  bottom: 16px;
  z-index: 50;
  display: flex;
  flex-direction: column;
  gap: 8px;
  max-width: min(440px, calc(100vw - 32px));
}
.toast {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 10px 10px 14px;
  background: var(--ink);
  color: var(--bg);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  animation: toast-in 0.18s ease-out;
}
.toast span {
  flex: 1;
}
.toast .btn {
  background: transparent;
  color: inherit;
  border-color: color-mix(in srgb, var(--bg) 40%, transparent);
}
.toast .btn:hover {
  background: color-mix(in srgb, var(--bg) 15%, transparent);
}
@keyframes toast-in {
  from {
    transform: translateY(8px);
    opacity: 0;
  }
}
.dialog {
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface);
  color: var(--ink);
  padding: 20px 24px;
  max-width: min(560px, calc(100vw - 24px));
  box-shadow: var(--shadow);
}
.dialog::backdrop {
  background: rgba(10, 15, 13, 0.45);
}
.dialog h2 {
  margin-top: 0;
  font-family: var(--font-head);
}
.shortcut-table {
  border-collapse: collapse;
  width: 100%;
  margin-bottom: 14px;
}
.shortcut-table th,
.shortcut-table td {
  text-align: left;
  padding: 7px 10px;
  border-bottom: 1px solid var(--line);
  vertical-align: top;
}

/* --- cards ---------------------------------------------------------------------------------- */
.card-grid {
  list-style: none;
  padding: 0;
  margin: 12px 0 0;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
  gap: 16px;
}
.card {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  overflow: hidden;
  display: flex;
  flex-direction: column;
}
.thumb {
  width: 100%;
  aspect-ratio: 14 / 9;
  display: block;
  background: var(--paper);
  border-bottom: 1px solid var(--line);
}
.card-body {
  padding: 12px 14px 14px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  flex: 1;
}
.card-title {
  margin: 0;
  font-family: var(--font-head);
  font-size: 1.2rem;
  display: flex;
  align-items: center;
  gap: 8px;
}
.card-text {
  margin: 0 0 6px;
  color: var(--ink-soft);
  flex: 1;
}
.card-body .btn {
  align-self: flex-start;
}
.badge {
  display: inline-block;
  font-family: var(--font-ui);
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  padding: 1px 7px;
  border-radius: 999px;
  vertical-align: middle;
}
.badge-2d {
  background: var(--accent-soft);
  color: var(--accent-ink);
}
.badge-3d {
  background: color-mix(in srgb, var(--accent-2) 22%, transparent);
  color: color-mix(in srgb, var(--accent-2) 70%, var(--ink));
}

/* --- challenges -------------------------------------------------------------------------------- */
.challenges-layout {
  display: grid;
  grid-template-columns: 260px 1fr;
  gap: 18px;
  align-items: start;
}
.challenge-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.challenge-link {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 9px 12px;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  background: var(--surface);
  color: var(--ink);
  text-decoration: none;
}
.challenge-link:hover {
  border-color: var(--axis);
}
.challenge-link.is-current {
  border-color: var(--accent);
  box-shadow: inset 3px 0 0 var(--accent);
}
.challenge-num {
  width: 24px;
  height: 24px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: var(--surface-2);
  font-weight: 700;
  font-size: 0.85rem;
  flex: none;
}
.challenge-name {
  flex: 1;
  font-weight: 560;
}
.passed-mark {
  color: var(--accent);
  display: inline-flex;
}
.challenge-detail {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 16px 18px 20px;
  min-width: 0;
}
.challenge-detail h2 {
  margin: 0 0 4px;
  font-family: var(--font-head);
}
.task {
  font-size: 1.05rem;
  margin-top: 4px;
}
.challenge-grid {
  display: grid;
  grid-template-columns: minmax(240px, 1fr) minmax(280px, 1.2fr);
  gap: 18px;
}
.challenge-figure {
  margin: 0;
}
.challenge-canvas {
  width: 100%;
  height: 260px;
  display: block;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  background: var(--paper);
}
.challenge-figure figcaption {
  color: var(--muted);
  font-size: 0.88rem;
  margin-top: 6px;
}
.challenge-work {
  display: flex;
  flex-direction: column;
  gap: 10px;
  min-width: 0;
}
.challenge-work .editor {
  height: 220px;
  flex: none;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
}
.field-label {
  font-weight: 650;
}
.row {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  align-items: center;
}
.hint summary,
.solution summary {
  cursor: pointer;
  color: var(--accent-ink);
  font-weight: 560;
}
.check-result:empty {
  display: none;
}
.check-result {
  padding: 10px 12px;
  border-radius: var(--radius-small);
  border-left: 4px solid var(--line);
  background: var(--surface-2);
}
.check-result.is-pass {
  border-left-color: var(--accent);
  background: var(--accent-soft);
}
.check-result.is-fail {
  border-left-color: var(--danger);
  background: var(--danger-soft);
}
.empty {
  text-align: center;
  padding: 30px;
  color: var(--ink-soft);
}

/* --- reference ------------------------------------------------------------------------------------ */
.reference-page {
  display: grid;
  grid-template-columns: 220px minmax(0, 1fr);
  gap: 8px 28px;
  max-width: 1200px;
}
.reference-page .page-head {
  grid-column: 1 / -1;
}
.toc {
  position: sticky;
  top: 76px;
  align-self: start;
}
.toc ul {
  list-style: none;
  margin: 0;
  padding: 0;
  border-left: 2px solid var(--line);
}
.toc a {
  display: block;
  padding: 4px 12px;
  color: var(--ink-soft);
  text-decoration: none;
}
.toc a:hover {
  color: var(--accent-ink);
}
.ref-section {
  grid-column: 2;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 4px 22px 18px;
  margin-bottom: 16px;
  scroll-margin-top: 80px;
}
.ref-section h2 {
  font-family: var(--font-head);
  font-size: 1.5rem;
  margin: 14px 0 8px;
}
.ref-section h2:focus {
  outline: none;
}
.ref-section li {
  margin-bottom: 6px;
}
.cmd {
  border-top: 1px solid var(--line);
  padding: 12px 0 4px;
}
.cmd-name {
  margin: 0;
  font-size: 1.05rem;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 4px;
}
.cmd-meta {
  margin: 2px 0;
  color: var(--muted);
  font-size: 0.9rem;
}
.example {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  margin: 8px 0;
}
.code-block {
  flex: 1;
  margin: 0;
  padding: 10px 14px;
  background: var(--surface-2);
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  font-family: var(--font-code);
  font-size: 0.9rem;
  line-height: 1.5;
  overflow-x: auto;
  white-space: pre;
}
.code-block .line {
  min-height: 1.5em;
}

/* --- responsive ---------------------------------------------------------------------------------- */
@media (max-width: 900px) {
  .workspace {
    grid-template-columns: 1fr;
  }
  .editor-panel {
    height: 46vh;
    min-height: 300px;
  }
  .view-panel {
    height: 62vh;
    min-height: 320px;
  }
  .speed {
    margin-left: 0;
  }
  .challenges-layout {
    grid-template-columns: 1fr;
  }
  .challenge-list {
    flex-direction: row;
    flex-wrap: wrap;
  }
  .challenge-grid {
    grid-template-columns: 1fr;
  }
  .reference-page {
    grid-template-columns: 1fr;
  }
  .toc {
    position: static;
  }
  .toc ul {
    display: flex;
    flex-wrap: wrap;
    border-left: 0;
    gap: 4px;
  }
  .toc a {
    border: 1px solid var(--line);
    border-radius: 999px;
    padding: 3px 10px;
    font-size: 0.9rem;
  }
  .ref-section {
    grid-column: 1;
    padding: 4px 14px 14px;
  }
}

@media (max-width: 560px) {
  .site-header {
    flex-wrap: wrap;
    gap: 6px 10px;
    padding: 8px 10px;
  }
  .site-nav {
    order: 3;
    flex-basis: 100%;
  }
  .header-tools {
    margin-left: auto;
  }
  .btn-label {
    display: none;
  }
  .toolbar .btn {
    min-width: 44px;
    min-height: 44px;
  }
  .seg-btn {
    min-height: 44px;
  }
  .speed input {
    width: 110px;
  }
  .panel-actions .btn span {
    display: none;
  }
  .example {
    flex-direction: column;
  }
  .example .code-block {
    width: 100%;
  }
  .challenge-link .challenge-name {
    font-size: 0.92rem;
  }
}

@media (prefers-reduced-motion: reduce) {
  * {
    animation: none !important;
    transition: none !important;
    scroll-behavior: auto !important;
  }
}
