/**
 * The real UI in a simulated DOM (happy-dom: no canvas, no WebGL).
 * Exercises window.logomocja and the user-facing controls; says nothing about pixels.
 */
import { beforeAll, describe, expect, test } from "bun:test";
import { Window } from "happy-dom";
import { run } from "../src/lang";

const win = new Window({ url: "http://localhost/Logomocja/builds/x/#/" });
const g = globalThis as Record<string, unknown>;
for (const k of ["window", "document", "navigator", "location", "history", "HTMLElement", "HTMLCanvasElement", "Node", "Event", "KeyboardEvent", "PointerEvent", "getComputedStyle", "localStorage", "matchMedia", "ResizeObserver", "requestAnimationFrame", "cancelAnimationFrame", "Blob", "DOMParser"]) {
  const v = (win as unknown as Record<string, unknown>)[k];
  if (v !== undefined) g[k] = v;
}
g.window = win;

type Hook = { version: string; run: typeof run; open(s: string, m: "2d" | "3d"): Promise<ReturnType<typeof run>> };
let api: Hook;
const $ = (sel: string) => win.document.querySelector(sel) as unknown as HTMLElement | null;
const tick = () => new Promise((r) => setTimeout(r, 40));
const key = (init: KeyboardEventInit) => win.document.dispatchEvent(new win.KeyboardEvent("keydown", { bubbles: true, ...init }) as unknown as Event);

beforeAll(async () => {
  win.document.body.innerHTML = '<div id="app"></div>';
  await import("../src/main");
  api = (win as unknown as { logomocja: Hook }).logomocja;
});

describe("UI: testing hook", () => {
  test("window.logomocja exposes version, run and open", () => {
    expect(typeof api.version).toBe("string");
    expect(api.run("np 10", "2d")).toEqual(run("np 10", "2d"));
  });

  test("open puts the program in the editor and resolves to the interpreter's result", async () => {
    const src = "powtorz 4 [np 100 pw 90]";
    expect(await api.open(src, "2d")).toEqual(run(src, "2d"));
    expect(($("#program-editor") as HTMLTextAreaElement).value).toBe(src);
    expect($('[data-mode="2d"]')!.getAttribute("aria-pressed")).toBe("true");
  });

  test("an error is marked inline at its line, with the Polish message", async () => {
    const r = await api.open("np 10\nnp )", "2d");
    expect(r.error).toMatchObject({ line: 2, column: 4 });
    expect($(".gutter-line.is-error")!.textContent).toBe("2");
    expect($(".inline-error")!.textContent).toBe(r.error!.message);
    expect($(".error-box")!.textContent).toContain("Wiersz 2, kolumna 4");
  });

  test("without WebGL a 3D program still runs and the app says why 3D is off", async () => {
    const r = await api.open("gora 90 np 10", "3d");
    expect(r).toEqual(run("gora 90 np 10", "3d"));
    expect($(".view-note")!.hidden).toBe(false);
    expect($(".view-note")!.textContent).toContain("WebGL");
  });
});

describe("UI: controls and shortcuts", () => {
  test("Alt+K steps one command and highlights its line; Alt+R resets", async () => {
    await api.open("np 10\npw 90\nnp 20", "2d");
    key({ code: "KeyR", key: "r", altKey: true });
    key({ code: "KeyK", key: "k", altKey: true });
    key({ code: "KeyK", key: "k", altKey: true });
    expect($(".gutter-line.is-exec")!.textContent).toBe("2");
    expect($(".status-text")!.textContent).toContain("Wstrzymano");
    key({ code: "KeyR", key: "r", altKey: true });
    expect($(".gutter-line.is-exec")).toBeNull();
    expect($(".status-text")!.textContent).toContain("Gotowy");
  });

  test("typing while paused stops the program and tells the user", async () => {
    await api.open("np 10\npw 90\nnp 20", "2d");
    key({ code: "KeyK", key: "k", altKey: true });
    const ta = $("#program-editor") as HTMLTextAreaElement;
    ta.value = "np 5";
    ta.dispatchEvent(new win.Event("input") as unknown as Event);
    expect($(".status-text")!.textContent).toContain("zatrzymany");
  });

  test("every button has an accessible name", () => {
    for (const b of win.document.querySelectorAll("button")) {
      const name = (b.getAttribute("aria-label") ?? b.textContent ?? "").trim();
      expect(name.length).toBeGreaterThan(0);
    }
  });
});

describe("UI: pages", () => {
  test("hash routes show the reference, the examples and a challenge", async () => {
    win.location.hash = "#/pomoc";
    await tick();
    expect($(".reference-page")!.hidden).toBe(false);
    expect($("#ref-polecenia")!.textContent).toContain("przechyllewo");
    win.location.hash = "#/przyklady";
    await tick();
    expect(win.document.querySelectorAll(".example-card").length).toBe(13);
    win.location.hash = "#/wyzwania/trojkat";
    await tick();
    expect($(".challenge-detail h2")!.textContent).toContain("Trójkąt");
  });

  test("opening an example from the gallery loads it into the studio in its mode", async () => {
    win.location.hash = "#/przyklady";
    await tick();
    const btn = [...win.document.querySelectorAll(".example-card button")].find((b) => b.getAttribute("aria-label")?.includes("Helisa"))!;
    (btn as unknown as HTMLButtonElement).click();
    await tick();
    expect(($("#program-editor") as HTMLTextAreaElement).value).toContain("Spirala wznosi się ku górze.");
    expect($('[data-mode="3d"]')!.getAttribute("aria-pressed")).toBe("true");
  });
});
EOF
