cat >> tests/ui.test.ts <<'EOF'

describe("UI: challenge flow", () => {
  test("typing a correct program and pressing Sprawdź reports a pass and marks the task", async () => {
    win.location.hash = "#/wyzwania/szesciokat";
    await tick();
    const ta = $("#challenge-editor") as HTMLTextAreaElement;
    ta.value = "powtorz 6 [np 60 pw 60]";
    ta.dispatchEvent(new win.Event("input"));
    const check = ([...win.document.querySelectorAll(".challenge-work button")] as HTMLButtonElement[]).find((b) => b.textContent?.includes("Sprawdź"))!;
    check.click();
    expect($(".check-result")!.className).toContain("is-pass");
    expect($(".challenge-link.is-current .passed-mark")).not.toBeNull();
  });

  test("a wrong program reports a failure with a reason", async () => {
    const ta = $("#challenge-editor") as HTMLTextAreaElement;
    ta.value = "powtorz 5 [np 60 pw 72]";
    ta.dispatchEvent(new win.Event("input"));
    ([...win.document.querySelectorAll(".challenge-work button")] as HTMLButtonElement[]).find((b) => b.textContent?.includes("Sprawdź"))!.click();
    expect($(".check-result")!.className).toContain("is-fail");
    expect($(".check-result")!.textContent!.length).toBeGreaterThan(15);
  });
});
EOF
